                manhattan_distance_sum += abs(i - target_i) + abs(j - target_j)
                if (tile - 1) // N != i or (tile - 1) % N != j:
                    out_of_place_count += 1

    for i in range(N):
        prev_tile = None
        for j in range(N):
            tile = state[i][j]
            if tile != 0 and prev_tile is not None and (prev_tile - 1) // N == (tile - 1) // N:
