    N = len(state)
    manhattan_distance_sum = 0
    inversions = 0

    for i in range(N):
        for j in range(N):
            tile = state[i][j]
            if tile != 0:
                target_i, target_j = divmod(tile - 1, N)
                manhattan_distance_sum += abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        row = [state[i][j] for j in range(N) if state[i][j] != 0]
        sorted_row = sorted(row)
        inversions += sum(1 for k, x in enumerate(row) for l in range(k + 1, len(row)) if sorted_row.index(x) > sorted_row.index(row[l]))

    for j in range(N):
        col = [state[i][j] for i in range(N) if state[i][j] != 0]
        sorted_col = sorted(col)
        inversions += sum(1 for k, x in enumerate(col) for l in range(k + 1, len(col)) if sorted_col.index(x) > sorted_col.index(col[l]))

    return manhattan_distance_sum

