def score_state(state):
    N = len(state)
    manhattan_distance = 0
    linear_conflicts = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value == 0:
                continue
            target_i, target_j = divmod(value - 1, N)
            manhattan_distance += abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        row_seen = set()
        for j in range(N):
            value = state[i][j]
            if value == 0 or (value - 1) // N != i:
                continue
            if any(value < x and x != 0 and (x - 1) // N == i for x in row_seen):
                linear_conflicts += 1
            row_seen.add(value)

    for j in range(N):
        col_seen = set()
        for i in range(N):
            value = state[i][j]
            if value == 0 or (value - 1) % N != j:
                continue
            if any(value < x and x != 0 and (x - 1) % N == j for x in col_seen):
                linear_conflicts += 1
            col_seen.add(value)

    return manhattan_distance

def score_state(state):
