        for j in range(N):
            tile = state[i][j]
            if tile == 0:
                continue
            goal_i, goal_j = goal_positions[tile]
            manhattan_distance += abs(i - goal_i) + abs(j - goal_j)

            # Check for linear conflicts on the same row
            if i == goal_i:
                for k in range(N):
                    other_tile = state[i][k]
                    if other_tile != 0 and (other_tile // N, other_tile % N)[0] == i and j > k > goal_j:
                        linear_conflicts += 1

            # Check for linear conflicts on the same column
            if j == goal_j:
                for k in range(N):
                    other_tile = state[k][j]
                    if other_tile != 0 and (other_tile // N, other_tile % N)[1] == j and i > k > goal_i:
                        linear_conflicts += 1

    return manhattan_distance

