                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)
                row_seen[value] = True
                max_in_row = max(max_in_row, value)
                if any(row_seen[x] for x in range(max_in_row + 1, N + 1)):
                    row_out_of_order_penalty += 1

    for j in range(N):
        col_seen = [False] * (N + 1)
