def score_state(state):
    N = len(state)
    score = 0
    target_positions = {(value - 1) // N: (value - 1) % N for value in range(1, N * N)}

    def is_blocking(path_i, path_j, tile_i, tile_j):
        return ((path_i == tile_i and min(target_positions[tile_i][1], target_positions[path_i][1]) < tile_j < max(target_positions[tile_i][1], target_positions[path_i][1])) or
                (path_j == tile_j and min(target_positions[tile_j][0], target_positions[path_j][0]) < tile_i < max(target_positions[tile_j][0], target_positions[path_j][0])))

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = target_positions[value - 1]
                score += abs(i - target_i) + abs(j - target_j)
                blocking_tiles = sum(is_blocking(target_i, target_j, x, y) for x in range(N) for y in range(N) if state[x][y] != 0 and (x != i or y != j))
                score += blocking_tiles * 3

    return score

def score_state(state):
    N = len(state)
