        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                sequence_breaks_row[target_i].add((value, j))
                sequence_breaks_col[target_j].add((value, i))

    def count_sequence_breaks(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        breaks = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                breaks += 1
        return breaks

    for positions in sequence_breaks_row:
        score += count_sequence_breaks(positions)

    for positions in sequence_breaks_col:
        score += count_sequence_breaks(positions)

    return score

def score_state(state):
    N = len(state)
    score = 0
