                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_swaps_needed(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        swaps = 0
        visited = [False] * len(sorted_positions)

        for k in range(len(sorted_positions)):
            if not visited[k]:
                cycle_size = 0
                j = k

                while not visited[j]:
                    visited[j] = True
                    next_tile_value, _ = sorted_positions[j]
                    target_index = next((i for i, x in enumerate(positions) if x[0] == next_tile_value), -1)
                    j = target_index
                    cycle_size += 1

                if cycle_size > 0:
                    swaps += (cycle_size - 1)

        return swaps

    for positions in row_positions:
        score += count_swaps_needed(positions) * 3

    for positions in col_positions:
        score += count_swaps_needed(positions) * 3

    return score

