                score += 2

    score += total_product_distance * 0.1

    return score

def score_state(state):
    N = len(state)
    score = 0
    zero_pos = None

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value == 0:
                zero_pos = (i, j)
            elif value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)

    if zero_pos is not None:
        goal_zero_pos = (N - 1, N - 1)
        score += 2 * (abs(zero_pos[0] - goal_zero_pos[0]) + abs(zero_pos[1] - goal_zero_pos[1]))

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                blocking_tiles = 0
                if i < target_i and zero_pos[0] > i:
                    blocking_tiles += sum(1 for x in range(i + 1, target_i) if state[x][j] != 0)
                elif i > target_i and zero_pos[0] < i:
                    blocking_tiles += sum(1 for x in range(target_i + 1, i) if state[x][j] != 0)
                if j < target_j and zero_pos[1] > j:
                    blocking_tiles += sum(1 for y in range(j + 1, target_j) if state[i][y] != 0)
                elif j > target_j and zero_pos[1] < j:
                    blocking_tiles += sum(1 for y in range(target_j + 1, j) if state[i][y] != 0)
                score += blocking_tiles * 3

    return score

