                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def linear_conflicts(positions):
        conflicts = 0
        sorted_positions = sorted(positions, key=lambda x: x[1])
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][0] > sorted_positions[k + 1][0]:
                conflicts += 1
        return conflicts

    for positions in row_positions:
