        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                if i == target_i and state[i].count(0) < abs(j - target_j):
                    score += (abs(j - target_j) - state[i].count(0)) * 2
                elif j == target_j and [row[j] for row in state].count(0) < abs(i - target_i):
                    score += (abs(i - target_i) - [row[j] for row in state].count(0))

