        sorted_positions = sorted(positions, key=lambda x: x[0])
        conflicts = 0
        for k in range(len(sorted_positions)):
            if sorted_positions[k][1] != k:
                for l in range(k + 1, len(sorted_positions)):
                    if sorted_positions[l][0] < sorted_positions[k][0] and sorted_positions[l][1] < sorted_positions[k][1]:
                        conflicts += 3
        return conflicts

    for positions in row_positions:
        score += count_linear_conflicts(positions)

    for positions in col_positions:
        score += count_linear_conflicts(positions)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0 and (value - 1) // N != i or (value - 1) % N != j:
                score += 1.5

    return score

