def score_state(state):
    N = len(state)
    score = 0

    def euclidean_distance(x1, y1, x2, y2):
        return ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5

    def find_nearest_misplaced_neighbor(i, j, value, row_positions, col_positions):
        min_distance = float('inf')
        target_i, target_j = divmod(value - 1, N)

        for pos_value, pos in row_positions[target_i]:
            if pos != j:
                current_dist = euclidean_distance(target_i, target_j, i, pos)
                if current_dist < min_distance:
                    min_distance = current_dist

        for pos_value, pos in col_positions[target_j]:
            if pos != i:
                current_dist = euclidean_distance(target_i, target_j, pos, j)
                if current_dist < min_distance:
                    min_distance = current_dist

        return min_distance

    def count_obstructed_paths(state, i, j, target_i, target_j, visited):
        obstructed = 0
        for x in range(min(i, target_i) + 1, max(i, target_i)):
            if state[x][j] != 0 and (x, j) not in visited:
                visited.add((x, j))
                obstructed += 1
        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0 and (i, y) not in visited:
                visited.add((i, y))
                obstructed += 1
        return obstructed

    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                nearest_neighbor_dist = find_nearest_misplaced_neighbor(i, j, value, row_positions, col_positions)
                score += nearest_neighbor_dist
                obstructed_paths = count_obstructed_paths(state, i, j, *divmod(value - 1, N), set())
                score += obstructed_paths * 2

    return score

def score_state(state):
    N = len(state)
    score = 0
    total_displacement = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                total_displacement += distance

    # Geometric series penalty for cumulative displacement
    score += (total_displacement / (N * N)) ** 2

    # Penalty for tiles not in their correct row or column
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                if i != target_i or j != target_j:
                    score += 1

    return score

