def score_state(state):
    N = len(state)
    score = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]
    quadrants = [[set() for _ in range(2)] for _ in range(2)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))
                quadrant_x = (i >= N // 2)
                quadrant_y = (j >= N // 2)
                quadrants[quadrant_x][quadrant_y].add(value)

    def count_misplaced_neighbors(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    def count_quadrant_misplacements(quadrants):
        misplaced = 0
        expected_values = set(range(1, N*N + 1))
        for x in range(2):
            for y in range(2):
                current_values = quadrants[x][y]
                expected_in_quadrant = {value for value in expected_values if (divmod(value - 1, N)[0] >= N // 2) == x and (divmod(value - 1, N)[1] >= N // 2) == y}
                misplaced += len(expected_in_quadrant - current_values)
        return misplaced

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    score += count_quadrant_misplacements(quadrants) * 2

    return score

