                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                manhattan_distances[value] = (i, j, target_i, target_j)

    for value in range(1, N * N):
        i, j, target_i, target_j = manhattan_distances[value]
        if i != target_i:
            for x in range(min(i, target_i) + 1, max(i, target_i)):
                if state[x][j] != 0:
                    blocked_tiles[value] += 1
        if j != target_j:
            for y in range(min(j, target_j) + 1, max(j, target_j)):
                if state[i][y] != 0:
                    blocked_tiles[value] += 1

    for value, (i, j, target_i, target_j) in manhattan_distances.items():
        score += blocked_tiles[value] * 2
        if i != target_i or j != target_j:
            edge_proximity_weight = min(i, N - i - 1, j, N - j - 1)
            score += (edge_proximity_weight / (N - 1)) * 1.5

