        value = state[i][j]
        if value == 0: 
            return 0
        target_i, target_j = divmod(value - 1, N)
        neighbor_sum = 0
        for x in range(i - 1, i + 2):
            for y in range(j - 1, j + 2):
                if 0 <= x < N and 0 <= y < N and (x != i or y != j) and state[x][y] != 0:
                    neighbor_target_i, neighbor_target_j = divmod(state[x][y] - 1, N)
                    if abs(x - target_i) + abs(y - target_j) > abs(x - neighbor_target_i) + abs(y - neighbor_target_j):
                        neighbor_sum += abs(x - neighbor_target_i) + abs(y - neighbor_target_j)
        return neighbor_sum

    for i in range(N):
        for j in range(N):
            score += sum_neighbor_distances(state, i, j)

    return score

