            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = manhattan_distance(i, j, target_i, target_j)
                total_distance += distance
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    # Calculate linear conflicts in rows and columns
    def count_linear_conflicts(positions):
        conflicts = 0
        sorted_positions = sorted(positions, key=lambda x: x[1])
        for k in range(len(sorted_positions)):
            for l in range(k + 1, len(sorted_positions)):
                if sorted_positions[k][0] > sorted_positions[l][0]:
                    conflicts += 2
        return conflicts

    score += sum(count_linear_conflicts(positions) for positions in row_positions)
    score += sum(count_linear_conflicts(positions) for positions in col_positions)

    # Calculate obstructed paths
    def count_obstructed_paths(state, i, j, target_i, target_j):
        obstructed = 0
        for x in range(min(i, target_i) + 1, max(i, target_i)):
            if state[x][j] != 0:
                obstructed += 3
        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0:
                obstructed += 3
        return obstructed

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = count_obstructed_paths(state, i, j, target_i, target_j)
                score += obstructed_paths

    score += total_distance / N

    return score

