def score_state(state):
    N = len(state)
    score = 0

    def euclidean_distance(i1, j1, i2, j2):
        return ((i1 - i2) ** 2 + (j1 - j2) ** 2) ** 0.5

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                # Add Euclidean distance penalty for being misplaced within rows or columns
                if i == target_i:
                    for k in range(N):
                        if state[i][k] != 0 and k != j:
                            target_k = divmod(state[i][k] - 1, N)[1]
                            if (target_k < j and k > j) or (target_k > j and k < j):
                                score += euclidean_distance(i, j, i, k)
                elif j == target_j:
                    for k in range(N):
                        if state[k][j] != 0 and k != i:
                            target_k = divmod(state[k][j] - 1, N)[0]
                            if (target_k < i and k > i) or (target_k > i and k < i):
                                score += euclidean_distance(i, j, k, j)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                # Add penalties for directly blocking other tiles
                if i == target_i:
                    for k in range(min(j, target_j) + 1, max(j, target_j)):
                        if state[i][k] != 0:
                            score += 2
                elif j == target_j:
                    for k in range(min(i, target_i) + 1, max(i, target_i)):
                        if state[k][j] != 0:
                            score += 2

    return score

