        for value, pos in positions:
            if value not in visited:
                cycle_size = 0
                x = value
                while x not in visited:
                    visited.add(x)
                    _, idx = next(y for y in positions if y[0] == x)
                    x, _ = next(p for p in positions if p[1] == idx and p[0] != 0)
                    cycle_size += 1
                cycles += cycle_size - 1
        return cycles

    for positions in row_positions:
        score += count_cycles(positions) * 2

    for positions in col_positions:
        score += count_cycles(positions) * 2

