        value = state[i][j]
        neighbors = [
            (i - 1, j), (i + 1, j),
            (i, j - 1), (i, j + 1)
        ]
        consecutive_neighbors = sum(
            0 <= ni < N and 0 <= nj < N and state[ni][nj] in {value - 1, value + 1}
