                obstructed += 1
        return obstructed

    def count_out_of_place(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        out_of_place = sum(1 for k in range(len(sorted_positions)) if sorted_positions[k][1] != k)
        return out_of_place

    for positions in row_positions:
        score += cumulative_distance(positions) * 2
        score += count_out_of_place(positions)

