    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_inversions(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = 0
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                inversions += 1
        return inversions

    for positions in row_positions:
        score += count_inversions(positions) * 3

    for positions in col_positions:
        score += count_inversions(positions) * 3

    def adjacent_difference(i, j):
        value = state[i][j]
        target_i, target_j = divmod(value - 1, N)
        diff = abs(i - target_i) + abs(j - target_j)
        adjacent_tiles = []

        if i > 0 and state[i-1][j] != 0:
            adj_value = state[i-1][j]
            adj_target_i, adj_target_j = divmod(adj_value - 1, N)
            adjacent_tiles.append(abs((i-1) - adj_target_i) + abs(j - adj_target_j))
        if i < N-1 and state[i+1][j] != 0:
            adj_value = state[i+1][j]
            adj_target_i, adj_target_j = divmod(adj_value - 1, N)
            adjacent_tiles.append(abs((i+1) - adj_target_i) + abs(j - adj_target_j))
        if j > 0 and state[i][j-1] != 0:
            adj_value = state[i][j-1]
            adj_target_i, adj_target_j = divmod(adj_value - 1, N)
            adjacent_tiles.append(abs(i - adj_target_i) + abs((j-1) - adj_target_j))
        if j < N-1 and state[i][j+1] != 0:
            adj_value = state[i][j+1]
            adj_target_i, adj_target_j = divmod(adj_value - 1, N)
            adjacent_tiles.append(abs(i - adj_target_i) + abs((j+1) - adj_target_j))

        return diff + sum(adjacent_tiles)

    for i in range(N):
        for j in range(N):
            if state[i][j] != 0:
                score += adjacent_difference(i, j) / N

    return score

