def score_state(state):
    N = len(state)
    score = 0
    visited = [False] * (N * N + 1)
    permutation = [0] * (N * N + 1)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                permutation[value] = target_j * N + target_i

    def cycle_length(start):
        length = 0
        current = start
        while not visited[current]:
            visited[current] = True
            current = permutation[current] // N + (permutation[current] % N) * N + 1
            length += 1
        return max(0, length - 1)

    for value in range(1, N * N + 1):
        if not visited[value]:
            score += cycle_length(value)

    return score

