        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0:
                obstructed += 1
        return obstructed

    def center_proximity_weight(i, j, N):
        center_i = (N - 1) / 2.0
        center_j = (N - 1) / 2.0
        distance_to_center = abs(i - center_i) + abs(j - center_j)
        return (1 - (distance_to_center / (N-1)))

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    for i in range(N):
        for j in range(N):
