        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    def count_cycles(positions):
        visited = set()
        cycles = 0
        positions_dict = {value: pos for value, pos in positions}

        for value, pos in positions:
            if value not in visited:
                cycle_size = 0
                current_value = value
                while current_value not in visited:
                    visited.add(current_value)
                    target_pos = positions_dict[current_value]
                    next_value = state[target_pos[0]][target_pos[1]]
                    cycle_size += 1
                    current_value = next_value

                if cycle_size > 1:
                    cycles += cycle_size

        return cycles

    for positions in row_positions:
        score += count_misplaced_neighbors(positions) * 2

    for positions in col_positions:
        score += count_misplaced_neighbors(positions) * 2

    for i in range(N):
