def score_state(state):
    N = len(state)
    score = 0
    misplaced_in_row = [0] * N
    misplaced_in_col = [0] * N

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                euclidean_distance = ((i - target_i) ** 2 + (j - target_j) ** 2) ** 0.5
                score += distance * (euclidean_distance + 1) / 2

                if i != target_i:
                    misplaced_in_row[target_i] += 1
                if j != target_j:
                    misplaced_in_col[target_j] += 1

                row_misplaced = sum(1 for v in state[i] if v != 0 and divmod(v - 1, N)[0] != i)
                col_misplaced = sum(1 for r in range(N) if state[r][j] != 0 and divmod(state[r][j] - 1, N)[1] != j)

                score += (row_misplaced + col_misplaced) * (factorial(misplaced_in_row[target_i] + misplaced_in_col[target_j]) / factorial(max(1, misplaced_in_row[target_i] + misplaced_in_col[target_j] - 2)))

    return score

def factorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        result = 1
        for k in range(2, n + 1):
            result *= k
        return result

