def score_state(state):
    N = len(state)
    score = 0

    def manhattan_distance(i, j, target_i, target_j):
        return abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = manhattan_distance(i, j, target_i, target_j)
                score += distance * (distance + 1) / 2

    def longest_obstructed_path(state, i, j, target_i, target_j):
        obstructed_row = max(0, max((state[x][j] != 0 for x in range(min(i, target_i) + 1, max(i, target_i)))) - 1)
        obstructed_col = max(0, max((state[i][y] != 0 for y in range(min(j, target_j) + 1, max(j, target_j)))) - 1)
        return obstructed_row + obstructed_col

    def blocking_shortest_path(state):
        blocked_count = 0
        for i in range(N):
            row_values = [state[i][j] for j in range(N)]
            sorted_row_values = sorted(row_values)
            for j in range(N):
                if row_values[j] != sorted_row_values[j]:
                    target_i, _ = divmod(sorted_row_values[j] - 1, N)
                    if i == target_i:
                        blocked_count += 1
        for j in range(N):
            col_values = [state[i][j] for i in range(N)]
            sorted_col_values = sorted(col_values)
            for i in range(N):
                if col_values[i] != sorted_col_values[i]:
                    _, target_j = divmod(sorted_col_values[i] - 1, N)
                    if j == target_j:
                        blocked_count += 1
        return blocked_count

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = longest_obstructed_path(state, i, j, target_i, target_j)
                score += obstructed_paths * 5

    score += blocking_shortest_path(state) * 4

    return score

