        score += count_out_of_sequence(positions) * 2
        score += sum(obstructed_path(state, pos[0] // N, pos[1], (pos[0] - 1) // N, pos[1]) * 3 for pos in positions)

    for positions in col_positions:
        score += count_out_of_sequence(positions) * 2
        score += sum(obstructed_path(state, pos[0] // N, pos[1], pos[0] // N, (pos[0] - 1) % N) * 3 for pos in positions)

    return score

