        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = log_decay_obstructed_paths(state, i, j, target_i, target_j)
                score += obstructed_paths

    return score

