        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = sum(1 for k in range(len(sorted_positions) - 1) if sorted_positions[k][1] > sorted_positions[k + 1][1])
        return inversions

    def count_inaccessible_neighbors(state):
        inaccessible_count = 0
        visited = [[False] * N for _ in range(N)]

        def mark_accessible(i, j):
            if i < 0 or i >= N or j < 0 or j >= N or state[i][j] == 0 or visited[i][j]:
                return
            visited[i][j] = True
            mark_accessible(i + 1, j)
            mark_accessible(i - 1, j)
            mark_accessible(i, j + 1)
            mark_accessible(i, j - 1)

        zero_i, zero_j = next((i, j) for i in range(N) for j in range(N) if state[i][j] == 0)
        mark_accessible(zero_i, zero_j)

        for i in range(N):
            for j in range(N):
                if not visited[i][j]:
                    inaccessible_count += 1

        return inaccessible_count

    for positions in row_positions:
        score += count_inversions(positions) * 4

    for positions in col_positions:
        score += count_inversions(positions) * 4

    score += count_inaccessible_neighbors(state) * 5

