        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                blocking_tiles = count_blocking_tiles(state, i, j, target_i, target_j)
                score += blocking_tiles * 2

    score += total_distance / (N * 2)

    return score

def score_state(state):
    N = len(state)
    score = 0
    row_displacements = [0] * N
    col_displacements = [0] * N

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        fact = 1
        for k in range(2, n + 1):
            fact *= k
        return fact

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                row_displacements[target_i] += abs(j - target_j)
                col_displacements[target_j] += abs(i - target_i)

    for i in range(N):
        score += row_displacements[i] * 2.5
        score += col_displacements[i] * 2.5

    for i in range(N):
        row_values = [state[i][j] for j in range(N) if state[i][j] != 0]
        col_values = [state[j][i] for j in range(N) if state[j][i] != 0]

        row_misplaced = sum(1 for k in range(1, len(row_values)) if row_values[k] < row_values[k - 1])
        col_misplaced = sum(1 for k in range(1, len(col_values)) if col_values[k] < col_values[k - 1])

        score += factorial(row_misplaced) * 3
        score += factorial(col_misplaced) * 3

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                blocking_row = sum(1 for x in range(min(i, target_i) + 1, max(i, target_i)) if state[x][j] != 0)
                blocking_col = sum(1 for y in range(min(j, target_j) + 1, max(j, target_j)) if state[i][y] != 0)
                score += (blocking_row * blocking_col) * 5

    return score

