        out_of_place = sum(1 for k in range(len(sorted_positions)) if sorted_positions[k][1] != k)
        return out_of_place

    score += count_out_of_place(diag_positions_main) * 5
    score += count_out_of_place(diag_positions_anti) * 5

    for positions in row_positions:
        score += count_out_of_place(positions) * 4

    for positions in col_positions:
