                if divmod(state[i][j]-1, N)[0] == divmod(state[i][j-1]-1, N)[0]:
                    if state[i][j] < state[i][j-1]:
                        misplaced_in_row += 1
        score += exponential_decay(misplaced_in_row, base=1.5)

    for j in range(N):
        misplaced_in_col = 0
        for i in range(1, N):
            if state[i][j] != 0 and state[i-1][j] != 0:
                if divmod(state[i][j]-1, N)[1] == divmod(state[i-1][j]-1, N)[1]:
                    if state[i][j] < state[i-1][j]:
