        misplaced = sum(1 for k in range(len(sorted_positions) - 1) if sorted_positions[k][1] > sorted_positions[k + 1][1])
        score += misplaced * (N - len(sorted_positions))

    def count_obstructed_paths(state, i, j, target_i, target_j):
        obstructed = 0
        for x in range(min(i, target_i) + 1, max(i, target_i)):
