        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] == sorted_positions[k - 1][1] + 1:
                current_cluster_size += 1
            else:
                if current_cluster_size > 1:
                    clusters += current_cluster_size
                current_cluster_size = 1
        if current_cluster_size > 1:
            clusters += current_cluster_size
        return clusters

    score += sum(count_misplaced_clusters(positions) * 3 for positions in row_positions)
    score += sum(count_misplaced_clusters(positions) * 2 for positions in col_positions)

