            if value != 0:
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def sequence_penalty(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        penalty = sum(1 for k in range(1, len(sorted_positions)) if sorted_positions[k][1] < sorted_positions[k - 1][1])
        return penalty

    for positions in row_positions:
        score += sequence_penalty(positions) * 5

    for positions in col_positions:
        score += sequence_penalty(positions) * 4

    def relative_position_penalty(state):
