    col_positions = [set() for _ in range(N)]

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        result = 1
        for k in range(2, n + 1):
            result *= k
        return result

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance * (distance + 1) / 2.5
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_misplaced_factorial(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = sum(1 for k in range(1, len(sorted_positions)) if sorted_positions[k][1] < sorted_positions[k - 1][1])
        return factorial(misplaced)

    for positions in row_positions:
        score += count_misplaced_factorial(positions) * 3

    for positions in col_positions:
        score += count_misplaced_factorial(positions) * 2

    obstructed_paths = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_x = sum(1 for x in range(min(i, target_i) + 1, max(i, target_i)) if state[x][j] != 0)
                obstructed_y = sum(1 for y in range(min(j, target_j) + 1, max(j, target_j)) if state[i][y] != 0)
                obstructed_paths += (obstructed_x + obstructed_y) * factorial(abs(i - target_i) + abs(j - target_j))

    score += obstructed_paths
    score += total_distance / (N * 3)

    return score

