                target_i, target_j = target_positions[value]
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance * (distance + 1) / 2

    # Detect cycles and count swaps needed
    def find_cycle_length(start):
        cycle_length = 0
        current = start
        while state[current[0]][current[1]] not in visited:
            visited.add(state[current[0]][current[1]])
            next_value = state[current[0]][current[1]]
            next_position = target_positions[next_value]
            current = next_position
            cycle_length += 1
        return max(0, cycle_length - 1)

    for i in range(N):
        for j in range(N):
            if state[i][j] != 0 and state[i][j] not in visited:
                cycle_length = find_cycle_length((i, j))
                score += cycle_length * 4

    score += total_distance / (N * 2)

    return score

