        row_conflicts = [set() for _ in range(N)]
        col_conflicts = [set() for _ in range(N)]
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i = (value - 1) // N
                target_j = (value - 1) % N
                if i == target_i and j > target_j and state[i][target_j] != 0 and (state[i][target_j] - 1) // N == i:
                    row_conflicts[target_i].add(min(j, target_j))
                if j == target_j and i > target_i and state[target_i][j] != 0 and (state[target_i][j] - 1) % N == j:
                    col_conflicts[target_j].add(min(i, target_i))
        for conflicts in row_conflicts + col_conflicts:
            score += len(conflicts) * (len(conflicts) - 1)
    return score

def score_state(state):
