def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distance
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)

    # Calculate row inversions penalty
    for i in range(N):
        row_seen = []
        for j in range(N):
            if state[i][j] != 0:
                row_seen.append(state[i][j])
        inversions = sum(1 for x, y in zip(row_seen, row_seen[1:]) if x > y)
        score += inversions * 0.5

    # Calculate column inversions penalty
    for j in range(N):
        col_seen = []
        for i in range(N):
            if state[i][j] != 0:
                col_seen.append(state[i][j])
        inversions = sum(1 for x, y in zip(col_seen, col_seen[1:]) if x > y)
        score += inversions * 0.5

    return score

def score_state(state):
    N = len(state)
    target_positions = {(i + 1): (i // N, i % N) for i in range(1, N * N)}
    manhattan_distance_sum = 0
    linear_conflicts = 0

    for row in range(N):
        row_tiles = [state[row][col] for col in range(N) if state[row][col] != 0]
        row_sorted = sorted(row_tiles, key=lambda x: target_positions[x][1])
        for i in range(len(row_sorted)):
            for j in range(i + 1, len(row_sorted)):
                if (target_positions[row_sorted[i]][1] > target_positions[row_sorted[j]][1] and
                    target_positions[row_sorted[i]][0] == target_positions[row_sorted[j]][0]):
                    linear_conflicts += 2

    for col in range(N):
        col_tiles = [state[row][col] for row in range(N) if state[row][col] != 0]
        col_sorted = sorted(col_tiles, key=lambda x: target_positions[x][0])
        for i in range(len(col_sorted)):
            for j in range(i + 1, len(col_sorted)):
                if (target_positions[col_sorted[i]][0] > target_positions[col_sorted[j]][0] and
                    target_positions[col_sorted[i]][1] == target_positions[col_sorted[j]][1]):
                    linear_conflicts += 2

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = target_positions[value]
                manhattan_distance_sum += abs(i - target_i) + abs(j - target_j)

    return manhattan_distance_sum

