            if sorted_values[k][1][1] > sorted_values[k + 1][1][1]:
                conflicts += 1
        return conflicts

    linear_conflicts = sum(count_conflicts(rc) for rc in row_conflicts) + sum(count_conflicts(cc) for cc in col_conflicts)

    score = manhattan_distance + 2 * linear_conflicts
    return score

