    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i = (value - 1) // N
                target_j = (value - 1) % N
                manhattan_score += abs(i - target_i) + abs(j - target_j)
                tile_positions[value] = (i, j)

    # Calculate linear conflict for rows
    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
        for k1 in range(len(row_tiles)):
            val1 = row_tiles[k1]
            target_i1, target_j1 = tile_positions[val1]
            if target_i1 == i:
                for k2 in range(k1 + 1, len(row_tiles)):
                    val2 = row_tiles[k2]
                    target_i2, target_j2 = tile_positions[val2]
                    if target_i2 == i and target_j1 > target_j2:
                        linear_conflict += 2

    # Calculate linear conflict for columns
    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0]
        for k1 in range(len(col_tiles)):
            val1 = col_tiles[k1]
            target_i1, target_j1 = tile_positions[val1]
            if target_j1 == j:
                for k2 in range(k1 + 1, len(col_tiles)):
                    val2 = col_tiles[k2]
                    target_i2, target_j2 = tile_positions[val2]
                    if target_j2 == j and target_i1 > target_i2:
                        linear_conflict += 2

    # Combine heuristic components with weights
    score = manhattan_score + 0.5 * linear_conflict
    return score

