                linear_conflicts += 1
            row_seen.add(value)

    for j in range(N):
        col_seen = set()
        for i in range(N):
            value = state[i][j]
            if value == 0 or (value - 1) % N != j:
                continue
            if any(value < x and x != 0 and (x - 1) % N == j for x in col_seen):
                linear_conflicts += 1
            col_seen.add(value)

    return manhattan_distance

def score_state(state):
