            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)

                # Count inversions in rows
                for k in range(j + 1, N):
                    if state[i][k] != 0 and value > state[i][k]:
                        row_inversions[i] += 1

                # Count inversions in columns
                for k in range(i + 1, N):
                    if state[k][j] != 0 and value > state[k][j]:
                        col_inversions[target_j] += 1

    # Penalize based on inversion counts, scaled by puzzle size
    linear_conflicts = sum(row_inversions) + sum(col_inversions)
    score = manhattan_distance + (N * linear_conflicts)

    return score

