            if value != 0 and next_value != 0:
                target_j = (value - 1) % N
                next_target_j = (next_value - 1) % N
                if target_j < next_target_j and (value - 1) // N == (next_value - 1) // N:
                    score -= 0.25

    for j in range(N):
        for i in range(N - 1):
            value = state[i][j]
            next_value = state[i + 1][j]
            if value != 0 and next_value != 0:
                target_i = (value - 1) // N
                next_target_i = (next_value - 1) // N
                if target_i < next_target_i and (value - 1) % N == (next_value - 1) % N:
                    score -= 0.25

