def score_state(state):
    N = len(state)
    manhattan_distance = 0
    misplaced_penalty = 0
    row_order_bonus = 0
    col_order_bonus = 0

    for i in range(N):
        prev_value_row = -1
        consecutive_count_row = 0
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)
                if i != target_i or j != target_j:
                    misplaced_penalty += 1
                if prev_value_row == value - 1:
                    consecutive_count_row += 1
                else:
                    row_order_bonus += consecutive_count_row * (consecutive_count_row - 1) / 2
                    consecutive_count_row = 0
            prev_value_row = value
        row_order_bonus += consecutive_count_row * (consecutive_count_row - 1) / 2

    for j in range(N):
        prev_value_col = -1
        consecutive_count_col = 0
        for i in range(N):
