                else:
                    col_order_bonus += consecutive_count_col * (consecutive_count_col - 1) / 2
                    consecutive_count_col = 0
            prev_value_col = value
        col_order_bonus += consecutive_count_col * (consecutive_count_col - 1) / 2

    score = manhattan_distance + misplaced_penalty * 2 - row_order_bonus - col_order_bonus
    return score

