                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)
                if prev_value_row != -1 and (prev_value_row != value - 1 or value != prev_value_row + 1):
                    row_order_penalty += abs(target_j - j) * (abs(i - target_i) + abs(j - target_j))
                misplaced_neighbors = sum(1 for ni, nj in [(-1,0), (1,0), (0,-1), (0,1)] if 0 <= i+ni < N and 0 <= j+nj < N and state[i+ni][j+nj] != 0 and abs(state[i+ni][j+nj] - value) > 1)
                misplaced_neighbors_penalty += misplaced_neighbors
                prev_value_row = value

    for j in range(N):
        prev_value_col = -1
        for i in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                if prev_value_col != -1 and (prev_value_col != value - 1 or value != prev_value_col + 1):
                    col_order_penalty += abs(target_i - i) * (abs(i - target_i) + abs(j - target_j))
                prev_value_col = value

    score = manhattan_distance + row_order_penalty + col_order_penalty + misplaced_neighbors_penalty
    return score

