                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                misplaced_tiles_row[i] += (i != target_i)
                misplaced_tiles_col[j] += (j != target_j)

    for i in range(N):
        score += misplaced_tiles_row[i] * 1 if misplaced_tiles_row[i] > 2 else 0
        score += misplaced_tiles_col[i] * 1 if misplaced_tiles_col[i] > 2 else 0

    # Bonus for adjacent tiles already in correct relative order with increased weights
    for i in range(N):
        for j in range(N - 1):
            value = state[i][j]
            next_value = state[i][j + 1]
            if value != 0 and next_value != 0:
                target_j = (value - 1) % N
                next_target_j = (next_value - 1) % N
                if target_j < next_target_j and (value - 1) // N == (next_value - 1) // N:
                    score -= 0.5

    for j in range(N):
        for i in range(N - 1):
            value = state[i][j]
            next_value = state[i + 1][j]
            if value != 0 and next_value != 0:
                target_i = (value - 1) // N
                next_target_i = (next_value - 1) // N
                if target_i < next_target_i and (value - 1) % N == (next_value - 1) % N:
                    score -= 0.5

    return score

def score_state(state):
    N = len(state)
