    misplaced_tiles_col = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                if i != target_i:
                    misplaced_tiles_row[target_i].add(value)
                if j != target_j:
                    misplaced_tiles_col[target_j].add(value)

    for tiles in misplaced_tiles_row + misplaced_tiles_col:
        for value in tiles:
            target_i, target_j = divmod(value - 1, N)
            current_i = next(i for i, row in enumerate(state) if value in row)
            current_j = state[current_i].index(value)
            score += abs(current_i - target_i) * 0.5 + abs(current_j - target_j) * 0.5

    return score

def score_state(state):
