                score += manhattan_distance
                # Penalty for blocking tiles in the path to goal position
                penalty = 0
                if i != target_i:
                    direction = 1 if i < target_i else -1
                    for k in range(i + direction, target_i + direction, direction):
                        if state[k][j] != 0 and (state[k][j] - 1) // N == target_i:
                            penalty += 1
                if j != target_j:
                    direction = 1 if j < target_j else -1
                    for k in range(j + direction, target_j + direction, direction):
                        if state[i][k] != 0 and (state[i][k] - 1) % N == target_j:
                            penalty += 1
                score += penalty * 0.5
    return score

