        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                manhattan_distance += distance * (N - distance) / N  # Linear decay factor
                if prev_value_row != -1 and value != prev_value_row + 1:
                    row_sequence_penalty += abs(target_j - j)
                prev_value_row = value

    for j in range(N):
