                target_i, target_j = divmod(value - 1, N)
                if prev_value_col != -1 and value != prev_value_col + 1:
                    col_sequence_penalty += abs(target_i - i)
                prev_value_col = value

    score = manhattan_distance + row_sequence_penalty + col_sequence_penalty
    return score

