            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)
                correct_positions[value] = (target_i, target_j)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = correct_positions[value]
                # Check adjacent tiles
                neighbors = [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]
                for ni, nj in neighbors:
                    if 0 <= ni < N and 0 <= nj < N:
                        neighbor_value = state[ni][nj]
                        if neighbor_value != 0:
                            correct_ni, correct_nj = correct_positions[neighbor_value]
                            if (correct_ni == ni or correct_nj == nj) and not ((correct_i == ni and correct_j == nj)):
                                adjacency_penalty += 1

    score = manhattan_distance + adjacency_penalty
    return score

