    col_conflicts = [{} for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance += abs(i - target_i) + abs(j - target_j)
                row_conflicts[i][value] = (target_j, j)
                col_conflicts[target_j][value] = (i, i)

    def count_conflicts(conflict_dict):
        conflicts = 0
        sorted_values = sorted(conflict_dict.items(), key=lambda x: x[1][0])
        for k in range(len(sorted_values) - 1):
            if sorted_values[k][1][1] > sorted_values[k + 1][1][1]:
                conflicts += 1
        return conflicts

    linear_conflicts = sum(count_conflicts(rc) * len(rc) for rc in row_conflicts) + sum(count_conflicts(cc) * len(cc) for cc in col_conflicts)

    score = manhattan_distance + linear_conflicts
    return score

