                    other_value = state[i][k]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if other_target_i == i and (target_j < k < other_target_j or other_target_j < k < target_j) and abs(target_i - i) + abs(j - k) > 0:
                            penalties[value] += 1

                # Check column conflicts
                for k in range(N):
                    other_value = state[k][j]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if other_target_j == j and (target_i < k < other_target_i or other_target_i < k < target_i) and abs(target_j - j) + abs(i - k) > 0:
                            penalties[value] += 1

    score = manhattan_distance + sum(penalties)
    return score

