    for positions in row_positions:
        score += count_inversions(positions)

    for positions in col_positions:
        score += count_inversions(positions)

    for positions in diagonal_positions:
        if len(positions) > 1:
            score += count_inversions(positions)

    for positions in anti_diagonal_positions:
