                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                # Penalty for being out of row or column order relative to the next expected tile
                if j < N - 1 and state[i][j + 1] != value + 1:
                    score += 2
                if i < N - 1 and state[i + 1][j] != value + N:
                    score += 2

    # Additional penalty for being misplaced within rows and columns
    for i in range(N):
        row_values = [state[i][j] for j in range(N) if state[i][j] != 0]
        col_values = [state[j][i] for j in range(N) if state[j][i] != 0]
        expected_row = sorted(row_values)
        expected_col = sorted(col_values)

        for k in range(len(row_values)):
            if row_values[k] != expected_row[k]:
                score += 1
            if col_values[k] != expected_col[k]:
                score += 1

    return score

