def score_state(state):
    N = len(state)
    score = 0
    manhattan_distances = {}
    misplaced_tiles_row = [[] for _ in range(N)]
    misplaced_tiles_col = [[] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                manhattan_distances[value] = (distance, i, j)
                misplaced_tiles_row[i].append((value, target_j))
                misplaced_tiles_col[j].append((value, target_i))

    for value in manhattan_distances:
        _, current_i, current_j = manhattan_distances[value]
        target_i, target_j = divmod(value - 1, N)

        # Count blocking tiles
        if current_i != target_i:
            for j in range(N):
                tile_value = state[current_i][j]
                if tile_value != 0 and (tile_value - 1) // N == target_i and min(current_j, target_j) <= j <= max(current_j, target_j) and tile_value != value:
                    score += 1
        if current_j != target_j:
            for i in range(N):
                tile_value = state[i][current_j]
                if tile_value != 0 and (tile_value - 1) % N == target_j and min(current_i, target_i) <= i <= max(current_i, target_i) and tile_value != value:
                    score += 1

    for row in misplaced_tiles_row:
        sorted_positions = sorted(row, key=lambda x: x[0])
        cumulative_displacement = 0
        for k in range(len(sorted_positions)):
            _, current_j = sorted_positions[k]
            target_j = (sorted_positions[k][0] - 1) % N
            cumulative_displacement += abs(current_j - target_j)
        score += cumulative_displacement

    for col in misplaced_tiles_col:
        sorted_positions = sorted(col, key=lambda x: x[0])
        cumulative_displacement = 0
        for k in range(len(sorted_positions)):
            _, current_i = sorted_positions[k]
            target_i = (sorted_positions[k][0] - 1) // N
            cumulative_displacement += abs(current_i - target_i)
        score += cumulative_displacement

    return score

