                                non_sequential_count += 1
        return non_sequential_count

    for positions in row_positions:
        score += count_misplaced_neighbors(positions)

    for positions in col_positions:
        score += count_misplaced_neighbors(positions)

    score += count_non_sequential_neighbors(state)

    return score

