    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_inversions(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = 0
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                inversions += 1
        return inversions

    def min_distance_to_correct(positions, target_row_or_col):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        distances = []
        for value, pos in positions:
            target_pos = (value - 1) % N if target_row_or_col == 'row' else (value - 1) // N
            distances.append(abs(pos - target_pos))
        return min(distances) if distances else 0

    for positions in row_positions:
        score += count_inversions(positions)
        score += sum(min_distance_to_correct(positions, 'row') for _ in range(len(positions)))

    for positions in col_positions:
        score += count_inversions(positions)
        score += sum(min_distance_to_correct(positions, 'col') for _ in range(len(positions)))

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Calculate average Manhattan distance of neighboring tiles
                neighbors = []
                for x in range(max(0, i-1), min(N, i+2)):
                    for y in range(max(0, j-1), min(N, j+2)):
                        if (x, y) != (i, j):
                            neighbor_value = state[x][y]
                            if neighbor_value != 0:
                                target_ni, target_nj = divmod(neighbor_value - 1, N)
                                neighbors.append(abs(x - target_ni) + abs(y - target_nj))

                if neighbors:
                    avg_neighbor_distance = sum(neighbors) / len(neighbors)
                    score += manhattan_distance * (avg_neighbor_distance / 10)

    return score

def score_state(state):
    N = len(state)
    score = 0
    zero_i = zero_j = -1

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value == 0:
                zero_i, zero_j = i, j
            else:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Weight based on proximity to the empty space
                distance_to_zero = abs(i - zero_i) + abs(j - zero_j)
                weight = (N - distance_to_zero) / N
                score += manhattan_distance * weight

                # Penalty for not being in correct row or column
                if i != target_i:
                    score += abs(i - target_i) * 1.5
                if j != target_j:
                    score += abs(j - target_j) * 1.5

    return score

def score_state(state):
    N = len(state)
    score = 0

    def count_obstacles(state, i, j, target_i, target_j):
        obstacles = 0
        if i < target_i:
            for x in range(i + 1, target_i):
                if state[x][j] != 0:
                    obstacles += 1
        elif i > target_i:
            for x in range(target_i + 1, i):
                if state[x][j] != 0:
                    obstacles += 1
        if j < target_j:
            for y in range(j + 1, target_j):
                if state[i][y] != 0:
                    obstacles += 1
        elif j > target_j:
            for y in range(target_j + 1, j):
                if state[i][y] != 0:
                    obstacles += 1
        return obstacles

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                obstacles = count_obstacles(state, i, j, target_i, target_j)
                score += obstacles * 2
                if (i != target_i or j != target_j):
                    row_misplaced = sum(1 for k in range(N) if state[i][k] != 0 and divmod(state[i][k] - 1, N)[0] != i)
                    col_misplaced = sum(1 for k in range(N) if state[k][j] != 0 and divmod(state[k][j] - 1, N)[1] != j)
                    score += row_misplaced + col_misplaced

    return score

