        obstacles_h = sum(1 for y in range(min(j, target_j) + 1, max(j, target_j)) if state[i][y] != 0)
        obstacles_v = sum(1 for x in range(min(i, target_i) + 1, max(i, target_i)) if state[x][j] != 0)
