                    inversions += 1
                if abs(sorted_positions[k][1] - sorted_positions[k + 1][1]) != 1:
                    mismatches += 1
            return inversions + mismatches

        score += count_inversions_mismatches(row_set)
        score += count_inversions_mismatches(col_set)

    for i in range(N):
        if misplaced_rows[i] > 0:
            score += misplaced_rows[i]
        if misplaced_cols[i] > 0:
            score += misplaced_cols[i]

    return score

