def score_state(state):
    N = len(state)
    score = 0
    manhattan_distances = {}
    misplaced_tiles_row = [[] for _ in range(N)]
    misplaced_tiles_col = [[] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                manhattan_distances[value] = (distance, i, j, target_i, target_j)
                misplaced_tiles_row[i].append((value, target_j))
                misplaced_tiles_col[j].append((value, target_i))

    for row in misplaced_tiles_row:
        row.sort(key=lambda x: x[1])
        for k in range(len(row) - 1):
            value_a, _ = row[k]
            value_b, _ = row[k + 1]
            if manhattan_distances[value_a][2] > manhattan_distances[value_b][2]:
                score += 3

    for col in misplaced_tiles_col:
        col.sort(key=lambda x: x[1])
        for k in range(len(col) - 1):
            value_a, _ = col[k]
            value_b, _ = col[k + 1]
            if manhattan_distances[value_a][1] > manhattan_distances[value_b][1]:
                score += 3

    for value, (_, i, j, target_i, target_j) in manhattan_distances.items():
        if i != target_i or j != target_j:
            score += 2

    return score

