def score_state(state):
    N = len(state)
    score = 0
    total_distance = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance

                # Count linear conflicts
                for x in range(N):
                    tile_value = state[x][j]
                    if tile_value != 0 and divmod(tile_value - 1, N)[0] == target_i and (x < i and target_i <= i) or (x > i and target_i >= i):
                        score += 2

                for y in range(N):
                    tile_value = state[i][y]
                    if tile_value != 0 and divmod(tile_value - 1, N)[1] == target_j and (y < j and target_j <= j) or (y > j and target_j >= j):
                        score += 2

    score += total_distance

    # Normalize the score
    normalization_factor = sum(range(N)) + N
    if normalization_factor > 0:
        score /= normalization_factor

    return score

