    score = 0

    def calculate_distance(value, i, j):
        target_i, target_j = divmod(value - 1, N)
        return abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        row = state[i]
        for j in range(N):
            value = row[j]
            if value != 0:
                distance = calculate_distance(value, i, j)
                score += distance
                if i > 0 and state[i-1][j] != 0 and calculate_distance(state[i-1][j], i-1, j) < distance:
                    score += distance * 2
                if i < N - 1 and state[i+1][j] != 0 and calculate_distance(state[i+1][j], i+1, j) < distance:
                    score += distance * 2
                if j > 0 and row[j-1] != 0 and calculate_distance(row[j-1], i, j-1) < distance:
                    score += distance * 2
                if j < N - 1 and row[j+1] != 0 and calculate_distance(row[j+1], i, j+1) < distance:
                    score += distance * 2

    return score

