                    obstacles += 1
        if j < target_j:
            for y in range(j + 1, target_j + 1):
                if state[i][y] != 0:
                    obstacles += 1
        elif j > target_j:
            for y in range(target_j, j):
                if state[i][y] != 0:
                    obstacles += 1
        return obstacles

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += max(abs(i - target_i), abs(j - target_j))  # Chebyshev distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    for positions in row_positions:
        sorted_positions = sorted(positions, key=lambda x: x[0])
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                score += 2

    for positions in col_positions:
        sorted_positions = sorted(positions, key=lambda x: x[0])
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                score += 2

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstacles = count_obstacles(state, i, j, target_i, target_j)
                score += obstacles * 3

    return score

def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]

    def find_cycles(i, j, current_cycle):
        if visited[i][j]:
            return False
        value = state[i][j]
        if value == 0:
            return False
        target_i, target_j = divmod(value - 1, N)
        if (target_i, target_j) in current_cycle:
            current_cycle.append((i, j))
            return True
        visited[i][j] = True
        current_cycle.append((i, j))
        return find_cycles(target_i, target_j, current_cycle)

    for i in range(N):
        for j in range(N):
            if not visited[i][j]:
                cycle = []
                if find_cycles(i, j, cycle):
                    score += len(cycle) * (len(cycle) - 1)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)

    return score

