        conflicts = 0
        for i in range(N):
            count = [0] * N
            for value, pos in positions[i]:
                target_pos = (value - 1) % N
                if pos < target_pos:
                    count[pos + 1:target_pos + 1] = [x + 1 for x in count[pos + 1:target_pos + 1]]
                elif pos > target_pos:
                    count[target_pos:pos] = [x + 1 for x in count[target_pos:pos]]
            conflicts += sum(count)
        return conflicts

    row_positions = [[] for _ in range(N)]
    col_positions = [[] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
