                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].append((value, j))
                col_positions[target_j].append((value, i))

    row_conflicts = calculate_conflicts(row_positions, N)
    col_conflicts = calculate_conflicts(col_positions, N)

    score += row_conflicts * 3
    score += col_conflicts * 3

    return score

