                if blocked:
                    score += 3

                # Surrounded by misplaced tiles
                surrounded = 0
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
