    correct_positions = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                manhattan_distances[value] = (distance, i, j, target_i, target_j)
                misplaced_tiles_row[i].append((value, target_j))
                misplaced_tiles_col[j].append((value, target_i))
                if i == target_i and j == target_j:
                    correct_positions.add(value)

    for row in misplaced_tiles_row:
        row.sort(key=lambda x: x[1])
        longest_chain = 0
        current_chain = 1
        for k in range(1, len(row)):
            value_a, _ = row[k - 1]
            value_b, _ = row[k]
            if manhattan_distances[value_a][2] < manhattan_distances[value_b][2]:
                current_chain += 1
            else:
                longest_chain = max(longest_chain, current_chain)
                current_chain = 1
        longest_chain = max(longest_chain, current_chain)
        score += longest_chain

    for col in misplaced_tiles_col:
        col.sort(key=lambda x: x[1])
        longest_chain = 0
        current_chain = 1
        for k in range(1, len(col)):
            value_a, _ = col[k - 1]
            value_b, _ = col[k]
            if manhattan_distances[value_a][1] < manhattan_distances[value_b][1]:
                current_chain += 1
            else:
                longest_chain = max(longest_chain, current_chain)
                current_chain = 1
        longest_chain = max(longest_chain, current_chain)
        score += longest_chain

    for value in correct_positions:
        distance, i, j, target_i, target_j = manhattan_distances[value]
        if distance == 0 and i == target_i and j == target_j:
            score -= 1

    return score

