        col_positions.sort(key=lambda x: x[0])

        for k in range(1, len(row_positions)):
            score += abs(row_positions[k][1] - row_positions[k-1][1]) * 0.5
        for k in range(1, len(col_positions)):
            score += abs(col_positions[k][1] - col_positions[k-1][1]) * 0.5

    return score

