                # Check if the current tile is blocking another tile's path
                if (i == target_i and any(state[i][y] != 0 for y in range(min(j, target_j) + 1, max(j, target_j)))):
                    score += 2
                elif (j == target_j and any(state[x][j] != 0 for x in range(min(i, target_i) + 1, max(i, target_i)))):
