            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance

                # Penalty for being out of row or column
                if i != target_i or j != target_j:
                    score += 1

                # Penalty for disrupting sequence within rows and columns
                next_value_row = value + 1 if (value + 1) % N != 0 else None
                next_value_col = value + N if value + N <= N * N - 1 else None

                if next_value_row:
                    ni, nj = divmod(next_value_row - 1, N)
                    for x in range(N):
                        if state[i][x] == next_value_row:
                            score += abs(j - nj) * 2
                            break

                if next_value_col:
                    ci, cj = divmod(next_value_col - 1, N)
                    for y in range(N):
                        if state[y][j] == next_value_col:
                            score += abs(i - ci) * 2
                            break

    return score

