        sorted_positions = sorted(positions, key=lambda x: x[0])
        penalty = 0
        for k in range(N - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                penalty += abs(sorted_positions[k][1] - sorted_positions[k + 1][1]) + N - 1 - abs(sorted_positions[k][1] - sorted_positions[k + 1][1])
        return penalty

    for i in range(N):
        row_positions = []
        col_positions = []
        for j in range(N):
