            if value != 0:
                _, target_j = divmod(value - 1, N)
                row_positions.append((value, target_j))
            value = state[j][i]
            if value != 0:
                target_i, _ = divmod(value - 1, N)
                col_positions.append((value, target_i))

        for k in range(N):
            for l in range(k + 1, N):
                if row_positions[k][1] > row_positions[l][1]:
                    score += abs(row_positions[k][1] - row_positions[l][1])
                if col_positions[k][1] > col_positions[l][1]:
                    score += abs(col_positions[k][1] - col_positions[l][1])

        score += calculate_circular_shift_penalty(row_positions)
        score += calculate_circular_shift_penalty(col_positions)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance

    return score

