        sorted_positions = sorted(positions, key=lambda x: x[0])
        metric = 0
        for k in range(len(sorted_positions)):
            if sorted_positions[k][1] != k:
                metric += 1
        return metric

    for positions in row_positions:
        score += permutation_metric(positions)

    for positions in col_positions:
        score += permutation_metric(positions)

    def linear_conflict(state):
        conflicts = 0
        N = len(state)
        target_positions = {value: divmod(value - 1, N) for value in range(1, N * N)}

        for i in range(N):
            row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
            row_target_cols = [target_positions[tile][1] for tile in row_tiles]

            for j in range(len(row_tiles)):
