    N = len(state)
    score = 0

    def manhattan_distance(i, j, target_i, target_j):
        return abs(i - target_i) + abs(j - target_j)

    misplaced_tiles_penalty = 0
    blocking_penalties = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += manhattan_distance(i, j, target_i, target_j)

                # Misplaced tiles penalty
                if i != target_i or j != target_j:
                    misplaced_tiles_penalty += 1

                # Blocking penalties
                for x in range(min(i, target_i) + 1, max(i, target_i)):
                    if state[x][j] != 0 and (state[x][j] - 1) // N == target_i:
                        blocking_penalties += 3

                for y in range(min(j, target_j) + 1, max(j, target_j)):
                    if state[i][y] != 0 and (state[i][y] - 1) % N == target_j:
                        blocking_penalties += 2

    score += misplaced_tiles_penalty * 4
    score += blocking_penalties

    return score

