        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                max_distance = max(max_distance, manhattan_distance)

    for i in range(N):
        row_positions = []
        col_positions = []
        for j in range(N):
            value = state[i][j]
            if value != 0:
                _, target_j = divmod(value - 1, N)
                row_positions.append((value, target_j))
            value = state[j][i]
            if value != 0:
                target_i, _ = divmod(value - 1, N)
                col_positions.append((value, target_i))

        for k in range(len(row_positions) - 1):
            for l in range(k + 1, len(row_positions)):
                if row_positions[k][1] > row_positions[l][1]:
                    score += 3

        for k in range(len(col_positions) - 1):
            for l in range(k + 1, len(col_positions)):
                if col_positions[k][1] > col_positions[l][1]:
                    score += 3

    score += max_distance * max_distance * 0.25

    return score

def score_state(state):
    N = len(state)
    score = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_inversions(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = 0
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                inversions += 1
        return inversions

    def count_obstructed_paths(state, i, j, target_i, target_j):
        obstructed = 0
        for x in range(min(i, target_i) + 1, max(i, target_i)):
            if state[x][j] != 0:
                obstructed += 1
        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0:
                obstructed += 1
        return obstructed

    inversion_penalty = 0.5
    obstructed_path_weight = 3

    for positions in row_positions:
        score += count_inversions(positions) * inversion_penalty

    for positions in col_positions:
        score += count_inversions(positions) * inversion_penalty

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = count_obstructed_paths(state, i, j, target_i, target_j)
                score += obstructed_paths * obstructed_path_weight

    return score

