def score_state(state):
    N = len(state)
    misplaced_tiles = 0
    linear_conflicts = 0

    for i in range(N):
        row_tiles = [tile for tile in state[i] if tile != 0]
        col_tiles = [state[j][i] for j in range(N) if state[j][i] != 0]

        for j, tile in enumerate(row_tiles):
            goal_i, goal_j = divmod(tile - 1, N)
            if (goal_i, goal_j) != (i, j + i * len(row_tiles)):
                misplaced_tiles += 1

        for j in range(len(row_tiles)):
            for k in range(j + 1, len(row_tiles)):
                if (row_tiles[j] - 1) // N == (row_tiles[k] - 1) // N and row_tiles[j] > row_tiles[k]:
                    linear_conflicts += 2

        for j, tile in enumerate(col_tiles):
            goal_i, goal_j = divmod(tile - 1, N)
            if (goal_i, goal_j) != (j + i * len(col_tiles), i):
                misplaced_tiles += 1

        for j in range(len(col_tiles)):
            for k in range(j + 1, len(col_tiles)):
                if (col_tiles[j] - 1) % N == (col_tiles[k] - 1) % N and col_tiles[j] > col_tiles[k]:
                    linear_conflicts += 2

    return misplaced_tiles

