def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Check for linear conflicts in rows
    for i in range(N):
        row = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row.sort()
        for k in range(len(row)):
            value, pos = row[k]
            goal_j = divmod(value - 1, N)[1]
            if pos != goal_j:
                for l in range(k + 1, len(row)):
                    next_value, next_pos = row[l]
                    next_goal_j = divmod(next_value - 1, N)[1]
                    if next_pos < goal_j and next_goal_j >= goal_j or next_pos > goal_j and next_goal_j <= goal_j:
                        score += 2

    # Check for linear conflicts in columns
    for j in range(N):
        col = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col.sort()
        for k in range(len(col)):
            value, pos = col[k]
            goal_i = divmod(value - 1, N)[0]
            if pos != goal_i:
                for l in range(k + 1, len(col)):
                    next_value, next_pos = col[l]
                    next_goal_i = divmod(next_value - 1, N)[0]
                    if next_pos < goal_i and next_goal_i >= goal_i or next_pos > goal_i and next_goal_i <= goal_i:
                        score += 2

    return score

