        for j in range(len(tiles_in_row)):
            for k in range(j + 1, len(tiles_in_row)):
                tile_j, tile_k = tiles_in_row[j], tiles_in_row[k]
                if (tile_j - 1) // N == (tile_k - 1) // N and sorted_tiles_in_row.index(tile_j) > sorted_tiles_in_row.index(tile_k):
                    linear_conflicts += 2

    for j in range(N):
        tiles_in_col = [state[i][j] for i in range(N) if state[i][j] != 0]
        sorted_tiles_in_col = sorted(tiles_in_col)
        for i in range(len(tiles_in_col)):
            for k in range(i + 1, len(tiles_in_col)):
                tile_i, tile_k = tiles_in_col[i], tiles_in_col[k]
                if (tile_i - 1) % N == (tile_k - 1) % N and sorted_tiles_in_col.index(tile_i) > sorted_tiles_in_col.index(tile_k):
                    linear_conflicts += 2

    return manhattan_distance

