                avg_penalty += penalty * 0.75 ** penalty
                count += 1

        if count > 0:
            score += avg_penalty / count

    row_displacements = [0] * N
    col_displacements = [0] * N

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                row_displacements[i] += abs(j - goal_j)
                col_displacements[j] += abs(i - goal_i)

    score += sum(disp * 0.8 for disp in row_displacements) + sum(disp * 0.8 for disp in col_displacements)

    return score

def score_state(state):
    N = len(state)
