                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                center_proximity = (N / 2 - abs(N / 2 - i)) * (N / 2 - abs(N / 2 - j))

                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                        n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                        if (ni != n_goal_i or nj != n_goal_j):
                            score += center_proximity * 0.5

    return score

def score_state(state):
    N = len(state)
    score = 0
    linear_conflicts = {}

    for i in range(N):
        row = state[i]
        col = [state[j][i] for j in range(N)]

        for j in range(N):
            value = row[j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                # Detect linear conflicts in rows
                for k in range(j + 1, N):
                    next_value = row[k]
                    if next_value != 0:
                        next_goal_i, next_goal_j = divmod(next_value - 1, N)
                        if i == goal_i and next_goal_i == goal_i and j > next_goal_j:
                            conflict_key = (min(value, next_value), max(value, next_value))
                            linear_conflicts[conflict_key] = linear_conflicts.get(conflict_key, 0) + 2

                # Detect linear conflicts in columns
                for k in range(j + 1, N):
                    next_value = col[k]
                    if next_value != 0:
                        next_goal_i, next_goal_j = divmod(next_value - 1, N)
                        if j == goal_j and next_goal_j == goal_j and i > next_goal_i:
                            conflict_key = (min(value, next_value), max(value, next_value))
                            linear_conflicts[conflict_key] = linear_conflicts.get(conflict_key, 0) + 2

    for conflict in linear_conflicts.values():
        score += conflict

    return score

