                min(goal_j, other_goal_j) <= current_j <= max(goal_j, other_goal_j) and
                min(goal_j, other_goal_j) <= other_current_j <= max(goal_j, other_goal_j)):
                score += 2

            if (current_j == other_current_j and
                min(goal_i, other_goal_i) <= current_i <= max(goal_i, other_goal_i) and
                min(goal_i, other_goal_i) <= other_current_i <= max(goal_i, other_goal_i)):
