                val_k, val_l = sorted_row[k], sorted_row[l]
                goal_k_j, goal_l_j = divmod(val_k - 1, N)[1], divmod(val_l - 1, N)[1]
                if goal_k_j > goal_l_j and i == divmod(val_k - 1, N)[0] == divmod(val_l - 1, N)[0]:
                    score += 2

