def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]

    def find_cycle(i, j, path):
        if (i, j) in path:
            return path[path.index((i, j)):]
        visited[i][j] = True
        goal_i, goal_j = divmod(state[i][j] - 1, N)
        for ni, nj in [(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)]:
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                if (ni, nj) == (goal_i, goal_j) or visited[ni][nj]:
                    continue
                cycle = find_cycle(ni, nj, path + [(i, j)])
                if cycle:
                    return cycle
        return []

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0 and not visited[i][j]:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    cycle = find_cycle(i, j, [])
                    if cycle:
                        score += len(cycle) * (len(cycle) - 1) / 2

    return score

