                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Inversions penalty
    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
        for k in range(len(row_tiles)):
            for l in range(k + 1, len(row_tiles)):
                value_k, value_l = row_tiles[k], row_tiles[l]
                goal_k_i, _ = divmod(value_k - 1, N)
                goal_l_i, _ = divmod(value_l - 1, N)
                if goal_k_i == i and goal_l_i == i and value_k > value_l:
                    score += 2

    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0]
        for k in range(len(col_tiles)):
            for l in range(k + 1, len(col_tiles)):
                value_k, value_l = col_tiles[k], col_tiles[l]
                _, goal_k_j = divmod(value_k - 1, N)
                _, goal_l_j = divmod(value_l - 1, N)
                if goal_k_j == j and goal_l_j == j and value_k > value_l:
                    score += 2

    # Linear conflict penalty with weighted sum
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles) - 1):
            for l in range(k + 1, len(row_tiles)):
                value_k, pos_k = row_tiles[k]
                value_l, pos_l = row_tiles[l]
                goal_k_i, goal_k_j = divmod(value_k - 1, N)
                goal_l_i, goal_l_j = divmod(value_l - 1, N)
                if goal_k_i == i and goal_l_i == i and pos_k > pos_l:
                    penalty = abs(goal_k_j - goal_l_j) * (abs(pos_k - pos_l))
                    score += 3 * penalty

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(len(col_tiles) - 1):
            for l in range(k + 1, len(col_tiles)):
                value_k, pos_k = col_tiles[k]
                value_l, pos_l = col_tiles[l]
                goal_k_i, goal_k_j = divmod(value_k - 1, N)
                goal_l_i, goal_l_j = divmod(value_l - 1, N)
                if goal_k_j == j and goal_l_j == j and pos_k > pos_l:
                    penalty = abs(goal_k_i - goal_l_i) * (abs(pos_k - pos_l))
                    score += 3 * penalty

    return score

