    col_displacements = [sum(abs(state[i][j] - (i * N + j + 1)) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j) for j in range(N)]

    score += sum(displacement for displacement in row_displacements)
    score += sum(displacement for displacement in col_displacements)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)

