def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    # Calculate Manhattan distances and identify misplaced tiles
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    # Find the position of the empty space
    empty_i, empty_j = next((i, j) for i in range(N) for j in range(N) if state[i][j] == 0)

    # Calculate penalties based on neighbors and distance to empty space
    for (i, j) in misplaced_tiles:
        min_penalty = float('inf')
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    distance_to_empty = abs(empty_i - ni) + abs(empty_j - nj)
                    weight_factor = max(1, (N // 2 - distance_to_empty) / (N // 2))
                    min_penalty = min(min_penalty, penalty * weight_factor)

        score += min_penalty

    # Row and column conflict penalties with increased factor for closer neighbors to goal
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles) - 1):
            for l in range(k + 1, len(row_tiles)):
                if row_tiles[k][1] > row_tiles[l][1]:
                    penalty = abs(row_tiles[k][1] - row_tiles[l][1]) * 0.75
                    goal_distance_k = abs(i - (row_tiles[k][0] - 1) // N)
                    goal_distance_l = abs(i - (row_tiles[l][0] - 1) // N)
                    score += 4 * penalty * max(goal_distance_k, goal_distance_l)

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(len(col_tiles) - 1):
            for l in range(k + 1, len(col_tiles)):
                if col_tiles[k][1] > col_tiles[l][1]:
                    penalty = abs(col_tiles[k][1] - col_tiles[l][1]) * 0.75
                    goal_distance_k = abs(j - (col_tiles[k][0] - 1) % N)
                    goal_distance_l = abs(j - (col_tiles[l][0] - 1) % N)
                    score += 4 * penalty * max(goal_distance_k, goal_distance_l)

    return score

