def score_state(state):
    N = len(state)
    score = 0

    def manhattan_distance(i, j, value):
        goal_i, goal_j = divmod(value - 1, N)
        return abs(i - goal_i) + abs(j - goal_j)

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                score += manhattan_distance(i, j, value)

    def linear_conflicts(tiles):
        conflicts = 0
        positions = {tile: idx for idx, tile in enumerate(tiles)}
        tiles_sorted = sorted(tiles, key=lambda x: divmod(x - 1, N))
        for k in range(1, len(tiles)):
            if positions[tiles_sorted[k]] < positions[tiles_sorted[k - 1]]:
                conflicts += 1
        return conflicts * 2

    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        score += linear_conflicts(row_tiles)

    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        score += linear_conflicts(col_tiles)

    decay_factor = 0.9
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                distance_to_goal = manhattan_distance(i, j, value)
                score += distance_to_goal * (decay_factor ** distance_to_goal)

    return score

