def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                # Check for blocking tiles
                blocked = False
                if i < goal_i:  # Tile needs to move down
                    for k in range(i + 1, goal_i):
                        block_value = state[k][j]
                        if block_value != 0 and (block_value - 1) // N == i:
                            blocked = True
                            break
                elif i > goal_i:  # Tile needs to move up
                    for k in range(goal_i + 1, i):
                        block_value = state[k][j]
                        if block_value != 0 and (block_value - 1) // N == goal_i:
                            blocked = True
                            break

                if j < goal_j:  # Tile needs to move right
                    for k in range(j + 1, goal_j):
                        block_value = state[i][k]
                        if block_value != 0 and (block_value - 1) % N == j:
                            blocked = True
                            break
                elif j > goal_j:  # Tile needs to move left
                    for k in range(goal_j + 1, j):
                        block_value = state[i][k]
                        if block_value != 0 and (block_value - 1) % N == goal_j:
                            blocked = True
                            break

                if blocked:
                    empty_i, empty_j = next((x, y) for x in range(N) for y in range(N) if state[x][y] == 0)
                    distance_to_empty = abs(i - empty_i) + abs(j - empty_j)
                    score += (manhattan_distance / max(1, distance_to_empty))

    return score

