def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for row in range(N):
        row_values = [state[row][j] for j in range(N)]
        sorted_row_values = sorted(row_values, key=lambda x: (x // N == row) * (divmod(x - 1, N)[1]))
        for k in range(len(sorted_row_values) - 1):
            if sorted_row_values[k] != 0 and sorted_row_values[k + 1] != 0:
                if divmod(sorted_row_values[k] - 1, N)[1] > divmod(sorted_row_values[k + 1] - 1, N)[1]:
                    score += abs(divmod(sorted_row_values[k] - 1, N)[1] - divmod(sorted_row_values[k + 1] - 1, N)[1]) * 2

    for col in range(N):
        col_values = [state[i][col] for i in range(N)]
        sorted_col_values = sorted(col_values, key=lambda x: (x % N == col) * (divmod(x - 1, N)[0]))
        for k in range(len(sorted_col_values) - 1):
            if sorted_col_values[k] != 0 and sorted_col_values[k + 1] != 0:
                if divmod(sorted_col_values[k] - 1, N)[0] > divmod(sorted_col_values[k + 1] - 1, N)[0]:
                    score += abs(divmod(sorted_col_values[k] - 1, N)[0] - divmod(sorted_col_values[k + 1] - 1, N)[0]) * 2

    for (i, j) in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        penalties = []

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    penalties.append(0)
                else:
                    relative_distance = abs(i - ni) + abs(j - nj)
                    weight_factor = (N - relative_distance) / N
                    penalties.append(penalty * weight_factor)

        score += sum(penalties) / len(penalties) if penalties else 0

    return score

