                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Inversion count penalties for rows and columns
    def count_inversions(lst):
        inversions = 0
        non_zero_tiles = [x for x in lst if x != 0]
        length = len(non_zero_tiles)
        for k in range(length):
            for l in range(k + 1, length):
                if non_zero_tiles[k] > non_zero_tiles[l]:
                    inversions += 1
        return inversions

    for i in range(N):
        row_inversions = count_inversions(state[i])
        score += row_inversions * (2 ** (N - len([x for x in state[i] if x != 0])))

    for j in range(N):
        col_tiles = [state[i][j] for i in range(N)]
        col_inversions = count_inversions(col_tiles)
        score += col_inversions * (2 ** (N - len([x for x in col_tiles if x != 0])))

    return score

