            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    dynamic_weight = (abs(empty_i - i) + abs(empty_j - j)) / (N * 2) + 2.0
                    min_penalty = min(min_penalty, penalty * dynamic_weight)

        score += min_penalty

    return score

