                        if state[i][k] != 0 and (state[i][k] - 1) // N == i and k != j:
                            block_goal_j = (state[i][k] - 1) % N
                            if (block_goal_j < goal_j and k > j) or (block_goal_j > goal_j and k < j):
                                score += 1

                if j == goal_j:
                    for k in range(N):
                        if state[k][j] != 0 and (state[k][j] - 1) % N == j and k != i:
                            block_goal_i = (state[k][j] - 1) // N
                            if (block_goal_i < goal_i and k > i) or (block_goal_i > goal_i and k < i):
                                score += 1

    # Calculate cumulative row and column distances for all tiles
    for value in range(1, N * N):
        i, j = divmod(value - 1, N)
        current_pos = None
        for x in range(N):
            if value in state[x]:
                current_pos = (x, state[x].index(value))
                break

        if current_pos:
            row_dist = abs(current_pos[0] - i) * N
            col_dist = abs(current_pos[1] - j) * N
            score += (row_dist + col_dist)

    return score

