            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                if (n_goal_i == goal_i or n_goal_j == goal_j) and ((n_goal_i != ni or n_goal_j != nj)):
                    obstruction_penalty += 2

        score += obstruction_penalty

    # Average Euclidean distance to neighboring misplaced tiles with decay
    for (i, j) in misplaced_tiles:
        value = state[i][j]
        total_euclidean_distance = 0
        neighbor_count = 0

        for ni, nj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ti, tj = i + ni, j + nj
            if 0 <= ti < N and 0 <= tj < N and state[ti][tj] != 0 and (ti, tj) in misplaced_tiles:
                n_value = state[ti][tj]
                total_euclidean_distance += ((abs(ti - i) ** 2 + abs(tj - j) ** 2) ** 0.5)
                neighbor_count += 1

        if neighbor_count > 0:
            average_distance = total_euclidean_distance / neighbor_count
            score += average_distance * 0.8

    return score

