    score = 0

    # Calculate Manhattan distances and quadrant penalties
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                # Quadrant penalty
                center_i, center_j = (N // 2), (N // 2)
                quadrant_penalty = ((abs(i - center_i) > center_i) + (abs(j - center_j) > center_j)) * value / N
                score += quadrant_penalty

    # Row and column linear conflict penalties
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles) - 1):
            if (row_tiles[k][0] - 1) // N == i and (row_tiles[k + 1][0] - 1) // N == i:
                if row_tiles[k][1] > row_tiles[k + 1][1]:
                    penalty = abs(row_tiles[k][1] - row_tiles[k + 1][1])
                    score += 2 * penalty

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(len(col_tiles) - 1):
            if (col_tiles[k][0] - 1) % N == j and (col_tiles[k + 1][0] - 1) % N == j:
                if col_tiles[k][1] > col_tiles[k + 1][1]:
                    penalty = abs(col_tiles[k][1] - col_tiles[k + 1][1])
                    score += 2 * penalty

    return score

def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distances for each misplaced tile
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Calculate penalties based on inversions in rows and columns
    for i in range(N):
        row_tiles = [state[i][j] for j in range(N) if state[i][j] != 0]
        row_inversions = sum(1 for k in range(len(row_tiles)) for l in range(k + 1, len(row_tiles)) 
                             if (row_tiles[k] - 1) // N == i and (row_tiles[l] - 1) // N == i and row_tiles[k] > row_tiles[l])
        score += row_inversions

    for j in range(N):
        col_tiles = [state[i][j] for i in range(N) if state[i][j] != 0]
        col_inversions = sum(1 for k in range(len(col_tiles)) for l in range(k + 1, len(col_tiles)) 
                             if (col_tiles[k] - 1) % N == j and (col_tiles[l] - 1) % N == j and col_tiles[k] > col_tiles[l])
        score += col_inversions

    # Adjust by considering the distance of misplaced tiles from their correct positions in terms of row and column parity
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                if (i % 2 != goal_i % 2) or (j % 2 != goal_j % 2):
                    score += 1

    return score

