def score_state(state):
    N = len(state)
    score = 0

    def calculate_manhattan_distance(i, j, value):
        goal_i, goal_j = divmod(value - 1, N)
        return abs(i - goal_i) + abs(j - goal_j)

    misplaced_tiles = set()
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                manhattan_distance = calculate_manhattan_distance(i, j, value)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for (i, j) in misplaced_tiles:
        cumulative_penalty = 0
        value = state[i][j]
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                cumulative_penalty += calculate_manhattan_distance(ni, nj, state[ni][nj])
        score += cumulative_penalty

        row_order_penalty = 0
        col_order_penalty = 0
        if i > 0 and state[i-1][j] != 0 and (state[i-1][j] - value) * N + j < (value - 1) * N + j:
            row_order_penalty += 2
        if i < N - 1 and state[i+1][j] != 0 and (state[i+1][j] - value) * N + j > (value - 1) * N + j:
            row_order_penalty += 2
        if j > 0 and state[i][j-1] != 0 and (state[i][j-1] - value) * N + j < (value - 1) * N + j:
            col_order_penalty += 2
        if j < N - 1 and state[i][j+1] != 0 and (state[i][j+1] - value) * N + j > (value - 1) * N + j:
            col_order_penalty += 2

        score += row_order_penalty + col_order_penalty

    return score

