                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                misplaced_tiles += (manhattan_distance > 0)

                row_count[value] += 1
                col_count[value] += 1

                if i != goal_i and j != goal_j:
                    score += 1

        for k in range(1, N + 1):
            if row_count[k] > 1 or col_count[k] > 1:
