def score_state(state):
    N = len(state)
    score = 0
    target_positions = {i: (i // N, i % N) for i in range(1, N * N)}

    # Calculate Manhattan distances and identify misplaced tiles
    misplaced_tiles = []
    for i in range(N):
        for j in range(N):
            tile = state[i][j]
            if tile != 0:
                goal_i, goal_j = target_positions[tile]
                score += abs(i - goal_i) + abs(j - goal_j)
                if (i, j) != (goal_i, goal_j):
                    misplaced_tiles.append((tile, i, j))

    # Detect cycles in rows and columns
    row_cycles = [set() for _ in range(N)]
    col_cycles = [set() for _ in range(N)]

    def find_cycle_length(cycles, idx, tile, pos, visited):
        if (idx, tile) in visited:
            return len(visited)
        cycles[idx].add((tile, pos))
        visited.add((idx, tile))
        next_tile, _, _ = next(((t, i, j) for t, i, j in misplaced_tiles if i == idx and j != target_positions[t][1] or j == idx and i != target_positions[t][0]), None)
        return find_cycle_length(cycles, idx, next_tile, pos + 1, visited) if next_tile else len(visited)

    for tile, i, j in misplaced_tiles:
        if (i, tile) not in row_cycles[i] and (j, tile) not in col_cycles[j]:
            cycle_length_row = find_cycle_length(row_cycles, i, tile, 0, set())
            cycle_length_col = find_cycle_length(col_cycles, j, tile, 0, set())
            score += max(cycle_length_row - 1, cycle_length_col - 1)

    return score

