def score_state(state):
    N = len(state)
    score = 0

    def calculate_manhattan_and_misplaced(i, j, value):
        goal_i, goal_j = divmod(value - 1, N)
        manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
        misplaced_in_row = i != goal_i
        misplaced_in_col = j != goal_j
        return manhattan_distance, misplaced_in_row, misplaced_in_col

    def nearest_misplaced_penalty(i, j):
        min_penalty = float('inf')
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                penalty = abs(ni - n_goal_i) + abs(nj - n_goal_j)
                min_penalty = min(min_penalty, penalty)
        return min_penalty

    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                manhattan_distance, misplaced_in_row, misplaced_in_col = calculate_manhattan_and_misplaced(i, j, value)
                score += manhattan_distance
                if misplaced_in_row or misplaced_in_col:
                    misplaced_tiles.add((i, j))

    def count_out_of_order(tiles):
        out_of_order_count = 0
        for i in range(len(tiles)):
            for j in range(i + 1, len(tiles)):
                if tiles[i] > tiles[j]:
                    out_of_order_count += 1
        return out_of_order_count

    rows_misplaced = [[] for _ in range(N)]
    cols_misplaced = [[] for _ in range(N)]

    for i, j in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        if i != goal_i:
            rows_misplaced[i].append(value)
        if j != goal_j:
            cols_misplaced[j].append(value)

    for row in rows_misplaced:
        score += count_out_of_order(row) * nearest_misplaced_penalty(i, j)

    for col in cols_misplaced:
        score += count_out_of_order(col) * nearest_misplaced_penalty(i, j)

    return score

