                    if other_value != 0 and j < k and other_goal_j < goal_j:
                        score += conflict_penalty
                        break
                for l in range(N):
                    other_value = state[l][j]
                    other_goal_i = (other_value - 1) // N
                    if other_value != 0 and i < l and other_goal_i < goal_i:
                        score += conflict_penalty
                        break

    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                # Check for linear conflicts on rows
                for k in range(j + 1, N):
                    neighbor_value = state[i][k]
                    if neighbor_value != 0:
                        neighbor_goal_i, neighbor_goal_j = divmod(neighbor_value - 1, N)
                        if i == neighbor_goal_i and goal_j > neighbor_goal_j:
                            score += 2
                # Check for linear conflicts on columns
                for k in range(i + 1, N):
                    neighbor_value = state[k][j]
                    if neighbor_value != 0:
                        neighbor_goal_i, neighbor_goal_j = divmod(neighbor_value - 1, N)
                        if j == neighbor_goal_j and goal_i > neighbor_goal_i:
                            score += 2
                # Check for misplaced tiles
                if (i, j) != (goal_i, goal_j):
                    misplaced_tiles += 1
    score += 0.5 * misplaced_tiles
    return score

