            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_in_row[i].add((value, j))
                    misplaced_in_col[j].add((value, i))

    # Penalize tiles not in correct sequence within rows and columns
    for i in range(N):
        row_sorted = sorted(misplaced_in_row[i], key=lambda x: x[1])
        col_sorted = sorted(misplaced_in_col[i], key=lambda x: x[1])

        for k in range(len(row_sorted) - 1):
            value_k, j_k = row_sorted[k]
            value_k1, j_k1 = row_sorted[k + 1]
            if (value_k != state[i][j_k] or value_k1 != state[i][j_k1]) and value_k > value_k1:
                score += abs(j_k - j_k1) * 0.5

        for k in range(len(col_sorted) - 1):
            value_k, i_k = col_sorted[k]
            value_k1, i_k1 = col_sorted[k + 1]
            if (value_k != state[i_k][i] or value_k1 != state[i_k1][i]) and value_k > value_k1:
                score += abs(i_k - i_k1) * 0.5

    return score

