def score_state(state):
    N = len(state)
    score = 0
    visited = set()
    center_i, center_j = N // 2, N // 2

    def find_cycle_length(positions, start, current_length=1):
        if positions[start] == start:
            return current_length
        visited.add(start)
        next_pos = positions[start]
        return find_cycle_length(positions, next_pos, current_length + 1)

    # Create a mapping from current position to goal position for each tile
    positions = [-1] * (N * N)
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                positions[value] = goal_i * N + goal_j

    # Calculate cycle lengths and add penalties for cycles longer than 2
    for i in range(1, N * N):
        if i not in visited:
            cycle_length = find_cycle_length(positions, i)
            if cycle_length > 2:
                score += (cycle_length - 2) * 3

    # Add Manhattan distances
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                distance_to_center = abs(i - center_i) + abs(j - center_j)
                if cycle_length > 2:
                    score += (cycle_length - 2) * (1 - (distance_to_center / (N // 2)))

    return score

