        misplaced_tiles_col[i].sort()

    for i in range(N):
        row_penalties = [float('inf')] * len(misplaced_tiles_row[i])
        col_penalties = [float('inf')] * len(misplaced_tiles_col[i])

        for k1 in range(len(misplaced_tiles_row[i])):
