                if j1 < j2:
                    row_penalties[k1] = min(row_penalties[k1], abs(j2 - goal_j1))
            for k2 in range(k1 - 1, -1, -1):
                j2, _ = misplaced_tiles_row[i][k2]
                if j1 > j2:
                    row_penalties[k1] = min(row_penalties[k1], abs(j2 - goal_j1))

        for k1 in range(len(misplaced_tiles_col[i])):
