def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Check for linear conflicts in rows
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles)):
            for l in range(k + 1, len(row_tiles)):
                tile1_value, tile1_pos = row_tiles[k]
                tile2_value, tile2_pos = row_tiles[l]
                goal1_i, goal1_j = divmod(tile1_value - 1, N)
                goal2_i, goal2_j = divmod(tile2_value - 1, N)
                if goal1_i == i and goal2_i == i and goal1_j > goal2_j:
                    score += 2

    # Check for linear conflicts in columns
    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(col_tiles)):
            for l in range(k + 1, len(col_tiles)):
                tile1_value, tile1_pos = col_tiles[k]
                tile2_value, tile2_pos = col_tiles[l]
                goal1_i, goal1_j = divmod(tile1_value - 1, N)
                goal2_i, goal2_j = divmod(tile2_value - 1, N)
                if goal1_j == j and goal2_j == j and goal1_i > goal2_i:
                    score += 2

    return score

def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]

    def get_goal_position(value):
        return divmod(value - 1, N)

    def find_cycle(i, j, path):
        if (i, j) in path:
            cycle_length = len(path) - path.index((i, j))
            return cycle_length
        visited[i][j] = True
        value = state[i][j]
        goal_i, goal_j = get_goal_position(value)
        path.append((i, j))
        for ni, nj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nni, nnj = i + ni, j + nj
            if 0 <= nni < N and 0 <= nnj < N and not visited[nni][nnj]:
                goal_ni, goal_nj = get_goal_position(state[nni][nnj])
                if goal_ni == i or goal_nj == j:
                    cycle_length = find_cycle(nni, nnj, path)
                    if cycle_length is not None:
                        return cycle_length
        path.pop()
        return None

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0 and not visited[i][j]:
                goal_i, goal_j = get_goal_position(value)
                score += abs(i - goal_i) + abs(j - goal_j)
                if i != goal_i or j != goal_j:
                    cycle_length = find_cycle(i, j, [])
                    if cycle_length is not None and cycle_length > 1:
                        score += (2 ** cycle_length) / 4

    return score

