                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i:
                    misplaced_tiles_row[i].add((j, value))
                if j != goal_j:
                    misplaced_tiles_col[j].add((i, value))

    # Calculate linear conflict penalty for rows and columns
    def calculate_conflict(misplaced_tiles):
        conflicts = 0
        sorted_tiles = sorted(misplaced_tiles)
        for i in range(len(sorted_tiles) - 1):
            if sorted_tiles[i][1] > sorted_tiles[i + 1][1]:
                conflicts += 1
        return conflicts * 2

    for row in misplaced_tiles_row:
        score += calculate_conflict(row)

    for col in misplaced_tiles_col:
        score += calculate_conflict(col)

    return score

