    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for (i, j) in misplaced_tiles:
        row_penalty, col_penalty = 0, 0
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)

        # Calculate average distance to next correctly placed tile in the row
        count_row, sum_row_dist = 0, 0
        for k in range(N):
            if k != j and state[i][k] != 0:
                other_goal_i, other_goal_j = divmod(state[i][k] - 1, N)
                if i == other_goal_i:
                    count_row += 1
                    sum_row_dist += abs(k - goal_j)

        # Calculate average distance to next correctly placed tile in the column
        count_col, sum_col_dist = 0, 0
        for k in range(N):
            if k != i and state[k][j] != 0:
                other_goal_i, other_goal_j = divmod(state[k][j] - 1, N)
                if j == other_goal_j:
                    count_col += 1
                    sum_col_dist += abs(k - goal_i)

        # Apply inverse distance weighting scheme for penalties
        if count_row > 0:
            row_penalty = (N / sum_row_dist) * 2 if sum_row_dist > 0 else N
        if count_col > 0:
            col_penalty = (N / sum_col_dist) * 2 if sum_col_dist > 0 else N

        score += row_penalty + col_penalty

    return score

def score_state(state):
