                score += manhattan_distance

                # Check for blocking tiles in the same row
                if i == goal_i and j != goal_j:
                    for k in range(min(j, goal_j), max(j, goal_j) + 1):
                        if state[i][k] != 0 and divmod(state[i][k] - 1, N)[0] != goal_i:
                            row_blocks[k] = True

                # Check for blocking tiles in the same column
                if j == goal_j and i != goal_i:
