        col_misplaced = sum(1 for j in range(N) if state[j][i] != 0 and (state[j][i] - 1) % N != i)
        score += row_misplaced_penalty * row_misplaced + col_misplaced_penalty * col_misplaced

    for i in range(N):
        for j in range(N):
            value = state[i][j]
