            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                score += abs(i - goal_i) + abs(j - goal_j)
                # Count row inversions
                for k in range(j):
                    other_value = state[i][k]
                    if other_value != 0 and value < other_value:
                        row_inversions += 1
                # Count column inversions
                for k in range(i):
