        for k in range(N):
            if state[i][k] != 0 and divmod(state[i][k] - 1, N)[0] == i:
                goal_j = (state[i][k] - 1) % N
                min_penalty_row = min(min_penalty_row, abs(j - goal_j))

        # Calculate column penalty
        for k in range(N):
            if state[k][j] != 0 and divmod(state[k][j] - 1, N)[1] == j:
                goal_i = (state[k][j] - 1) // N
                min_penalty_col = min(min_penalty_col, abs(i - goal_i))

        score += 2 * min(min_penalty_row, min_penalty_col)

    return score

def score_state(state):
    N = len(state)
    score = 0
    center_i, center_j = N // 2, N // 2

    for i in range(N):
