        for j1 in range(N-1):
            for j2 in range(j1 + 1, N):
                if state[i][j1] != 0 and state[i][j2] != 0 and state[i][j1] > state[i][j2]:
                    row_inversions += 1
        score += row_inversions * (2 - abs(i - center_i) / float(N // 2))

    for j in range(N):
        col_inversions = 0
        for i1 in range(N-1):
            for i2 in range(i1 + 1, N):
                if state[i1][j] != 0 and state[i2][j] != 0 and state[i1][j] > state[i2][j]:
                    col_inversions += 1
        score += col_inversions * (2 - abs(j - center_j) / float(N // 2))

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    return score

