                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                # Calculate blocking penalty
                for di in range(-manhattan_distance, manhattan_distance + 1):
                    for dj in range(-manhattan_distance, manhattan_distance + 1):
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
