                            ng_i, ng_j = divmod(n_value - 1, N)
                            if (ng_i == goal_i or ng_j == goal_j) and ((ni, nj) not in [(goal_i, x) for x in range(N)] + [(x, goal_j) for x in range(N)]):
                                blocked_tiles_penalty[n_value] += abs(ni - goal_i) + abs(nj - goal_j)

    score += sum(blocked_tiles_penalty) * 0.5
    return score

