            for l in range(k + 1, len(sorted_row_tiles)):
                next_value, next_pos = sorted_row_tiles[l]
                next_goal_j = divmod(next_value - 1, N)[1]
                if pos > next_pos and goal_j < next_goal_j:
                    score += 2

    # Calculate linear conflicts in columns
    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        sorted_col_tiles = sorted(col_tiles, key=lambda x: x[0])
        for k in range(len(sorted_col_tiles)):
            value, pos = sorted_col_tiles[k]
            goal_i = divmod(value - 1, N)[0]
            for l in range(k + 1, len(sorted_col_tiles)):
                next_value, next_pos = sorted_col_tiles[l]
                next_goal_i = divmod(next_value - 1, N)[0]
                if pos > next_pos and goal_i < next_goal_i:
                    score += 2

    return score

