                neighbor_value = state[ni][nj]
                neighbor_goal_i, neighbor_goal_j = divmod(neighbor_value - 1, N)

                # Check incorrect order penalty
                if (goal_i < i and ni >= goal_i) or (goal_i > i and ni <= goal_i) or \
                   (goal_j < j and nj >= goal_j) or (goal_j > j and nj <= goal_j):
                    incorrect_order_penalty += 1

                # Calculate distance to correctly positioned neighbor
                if neighbor_goal_i == ni and neighbor_goal_j == nj:
                    distance = abs(i - ni) + abs(j - nj)
                    if distance > 0:
                        neighbor_distances.append(1 / distance)

        if neighbor_distances:
            harmonic_mean_penalty = len(neighbor_distances) / sum(neighbor_distances)
        else:
            harmonic_mean_penalty = 2  # Default penalty if no correctly positioned neighbors

        score += incorrect_order_penalty * harmonic_mean_penalty

    return score

