                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                min_penalty = min(min_penalty, penalty)

        score += min_penalty

    row_conflicts = [0] * N
    col_conflicts = [0] * N

    for i in range(N):
        row_tiles = set()
        col_tiles = set()
        for j in range(N):
            if state[i][j] != 0:
