def score_state(state):
    N = len(state)
    score = 0
    parent = list(range(N * N))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    score += 1

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                neighbors = []
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                        neighbors.append(state[ni][nj])
                for neighbor in neighbors:
                    goal_i, goal_j = divmod(value - 1, N)
                    n_goal_i, n_goal_j = divmod(neighbor - 1, N)
                    if abs(goal_i - n_goal_i) + abs(goal_j - n_goal_j) == 1:
                        union(value - 1, neighbor - 1)

    cycle_sizes = {}
    for i in range(N * N):
        root = find(i)
        if root != i:  # Only consider non-singleton sets
            cycle_sizes[root] = cycle_sizes.get(root, 0) + 1

    for root, size in cycle_sizes.items():
        score += (size - 1) * 2  # Penalize longer disjoint cycles

    return score

def score_state(state):
    N = len(state)
    score = 0
    blocked_tiles_count = [set() for _ in range(N)]

    for i in range(N):
