                score += manhattan_distance
                if i == goal_i or j == goal_j:
                    blocked_tiles_count[goal_i].add((i, j))

    for i in range(N):
        row_tiles = sorted(blocked_tiles_count[i], key=lambda x: (x[0] if i != 0 else -x[1]))
        for k in range(len(row_tiles) - 1):
            score += abs(row_tiles[k][1] - row_tiles[k + 1][1]) * (k + 1)

    return score

