def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distances and identify misplaced tiles
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Linear conflict detection
    for i in range(N):
        row = [state[i][j] for j in range(N)]
        row = [x for x in row if x != 0]
        for k in range(len(row)):
            for l in range(k + 1, len(row)):
                goal_k_i, _ = divmod(row[k] - 1, N)
                goal_l_i, _ = divmod(row[l] - 1, N)
                if goal_k_i == i and goal_l_i == i and row[k] > row[l]:
                    score += 2

    for j in range(N):
        col = [state[i][j] for i in range(N)]
        col = [x for x in col if x != 0]
        for k in range(len(col)):
            for l in range(k + 1, len(col)):
                _, goal_k_j = divmod(col[k] - 1, N)
                _, goal_l_j = divmod(col[l] - 1, N)
                if goal_k_j == j and goal_l_j == j and col[k] > col[l]:
                    score += 2

    # Count inversions
    flat_state = [num for row in state for num in row if num != 0]
    inversions = 0
    for i in range(len(flat_state)):
        for j in range(i + 1, len(flat_state)):
            if flat_state[i] > flat_state[j]:
                inversions += 1
    score += inversions

    return score

