def score_state(state):
    N = len(state)
    score = 0

    def manhattan_distance(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    # Calculate Manhattan distances and identify misplaced tiles
    misplaced_tiles = []
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance_value = manhattan_distance(i, j, goal_i, goal_j)
                score += manhattan_distance_value
                if i != goal_i or j != goal_j:
                    misplaced_tiles.append((i, j, value))

    # Calculate penalties for tiles out-of-place relative to their nearest neighbors
    for (i, j, value) in misplaced_tiles:
        min_penalty = float('inf')
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                penalty = manhattan_distance(ni, nj, n_goal_i, n_goal_j)
                min_penalty = min(min_penalty, penalty)
        score += min_penalty

    # Calculate linear conflict penalties
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0]
        row_tiles.sort(key=lambda x: x[0])
        for j1 in range(len(row_tiles)):
            for j2 in range(j1 + 1, len(row_tiles)):
                value1, pos1 = row_tiles[j1]
                goal_i1, _ = divmod(value1 - 1, N)
                _, pos2 = row_tiles[j2]
                value2, _ = row_tiles[j2]
                goal_i2, _ = divmod(value2 - 1, N)
                if goal_i1 == i and goal_i2 == i and pos1 > pos2:
                    score += 2

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0]
        col_tiles.sort(key=lambda x: x[0])
        for i1 in range(len(col_tiles)):
            for i2 in range(i1 + 1, len(col_tiles)):
                value1, pos1 = col_tiles[i1]
                _, goal_j1 = divmod(value1 - 1, N)
                pos2, _ = col_tiles[i2]
                value2, _ = col_tiles[i2]
                _, goal_j2 = divmod(value2 - 1, N)
                if goal_j1 == j and goal_j2 == j and pos1 > pos2:
                    score += 2

    return score

