def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distances
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Detect cycles
    visited = [[False] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if not visited[i][j] and state[i][j] != 0:
                cycle_size = 0
                x, y = i, j
                while not visited[x][y]:
                    visited[x][y] = True
                    goal_x, goal_y = divmod(state[x][y] - 1, N)
                    if (x, y) == (goal_x, goal_y):
                        break
                    cycle_size += 1
                    x, y = goal_x, goal_y

                if cycle_size > 1:
                    score += (cycle_size - 1) * (N // 2)

    # Adjust by cumulative distance to correctly positioned neighbors
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0 and not all(state[x][y] == x * N + y + 1 for x, y in [i, j]):
                min_distance = float('inf')
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                        n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                        distance = abs(ni - n_goal_i) + abs(nj - n_goal_j)
                        min_distance = min(min_distance, distance)
                score += min_distance * (N // 2)

    return score

