            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0 and (ni, nj) not in visited:
                n_goal_i, n_goal_j = divmod(state[ni][nj] - 1, N)
                if abs(ni - goal_i) + abs(nj - goal_j) > 0:
                    min_recursive_penalty = min(min_recursive_penalty, recursive_penalty(ni, nj, visited | {(ni, nj)}))

        return penalty + (min_recursive_penalty * 0.75 if min_recursive_penalty != float('inf') else 0)

    score = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance_value = abs(i - goal_i) + abs(j - goal_j)
