                weight_factor = 1 / (penalty + 1)
                total_penalty += penalty * weight_factor
                count += 1

        if count > 0:
            score += total_penalty / count

    # Sliding scale factor for row and column penalties
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(1, len(row_tiles)):
            penalty = abs(row_tiles[k][1] - row_tiles[k - 1][1]) * (k / N)
            score += penalty

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
