        row_tiles.sort(key=lambda x: (x[0] - 1) % N)
        for j in range(len(row_tiles) - 1):
            for k in range(j + 1, len(row_tiles)):
                if row_tiles[j][1] > row_tiles[k][1]:
                    linear_conflicts += 2

