    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: (x[0] - 1) // N)
        for i in range(len(col_tiles) - 1):
            for k in range(i + 1, len(col_tiles)):
                if col_tiles[i][1] > col_tiles[k][1]:
                    linear_conflicts += 2

