def score_state(state):
    N = len(state)
    target_positions = {(value + 1) % (N * N): (i, j) for i in range(N) for j in range(N)}
    score = 0

    # Calculate row conflicts
    for i in range(N):
        tiles_in_row = [state[i][j] for j in range(N) if state[i][j] != 0 and target_positions[state[i][j]][0] == i]
        sorted_tiles = sorted(tiles_in_row, key=lambda x: target_positions[x][1])
        conflicts = sum(1 for k in range(len(sorted_tiles)) for l in range(k + 1, len(sorted_tiles))
                        if target_positions[sorted_tiles[k]][1] > target_positions[sorted_tiles[l]][1])
        score += 2 * conflicts

    # Calculate column conflicts
    for j in range(N):
        tiles_in_col = [state[i][j] for i in range(N) if state[i][j] != 0 and target_positions[state[i][j]][1] == j]
        sorted_tiles = sorted(tiles_in_col, key=lambda x: target_positions[x][0])
        conflicts = sum(1 for k in range(len(sorted_tiles)) for l in range(k + 1, len(sorted_tiles))
                        if target_positions[sorted_tiles[k]][0] > target_positions[sorted_tiles[l]][0])
        score += 2 * conflicts

    # Add Manhattan distances
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = target_positions[value]
                score += abs(i - target_i) + abs(j - target_j)

    return score

