    def count_conflicts(linear_index, is_row=True):
        conflicts = 0
        for i in range(N):
            tile1 = linear_index[i]
            if tile1 == 0:
                continue
            pos1 = target_positions[tile1]
            for j in range(i + 1, N):
                tile2 = linear_index[j]
                if tile2 == 0:
                    continue
                pos2 = target_positions[tile2]
                if (is_row and pos1[1] > pos2[1]) or (not is_row and pos1[0] > pos2[0]):
