        conflicts = 0
        tiles_in_place = []
        for idx, value in enumerate(row_or_col):
            if value != 0:
                target_idx = target_positions[value][1] if row_or_col is state[target_positions[value][0]] else target_positions[value][0]
                if (row_or_col is state[target_positions[value][0]] and target_positions[value][0] == idx) or \
                   (row_or_col is not state[target_positions[value][0]] and target_positions[value][1] == idx):
                    tiles_in_place.append((value, target_idx))
        tiles_in_place.sort(key=lambda x: x[1])
        for i in range(len(tiles_in_place) - 1):
            if tiles_in_place[i][1] > tiles_in_place[i + 1][1]:
                conflicts += 2
        return conflicts

    total_conflicts = sum(linear_conflicts(row) for row in state)
    total_conflicts += sum(linear_conflicts([state[j][i] for j in range(N)]) for i in range(N))

    return total_conflicts

