        for di in range(-1, 2):
            for dj in range(-1, 2):
                if (di == 0) != (dj == 0):  # Only one of di or dj should be non-zero
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N:
                        value = state[ni][nj]
                        target_i, target_j = divmod(value - 1, N)
                        if ni == target_i and nj == target_j:
                            return abs(i - ni) + abs(j - nj)
