def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distances and find the position of the empty slot
    empty_i, empty_j = None, None
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value == 0:
                empty_i, empty_j = i, j
            elif value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

    # Calculate sigmoid weighting factor based on misplaced neighbors around the empty slot
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    misplaced_neighbors = sum(
        1 for di, dj in directions
        if 0 <= empty_i + di < N and 0 <= empty_j + dj < N and state[empty_i + di][empty_j + dj] != 0
    )
    sigmoid_factor = 1 / (1 + 2.71828 ** (-misplaced_neighbors))

    # Apply row and column penalties with sigmoid weighting
    for i in range(N):
