                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (value - prev_value) % N not in [1, -N + 1]:
                        score += 1
                        misplaced_row_count[i] += 1

                # Check column sequence penalty
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if value - above_value != N:
                        score += 1
