def score_state(state):
    N = len(state)
    score = 0
    manhattan_distances = []
    row_correctness = [0] * N
    col_correctness = [0] * N

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                manhattan_distances.append(manhattan_distance)

                # Check row correctness
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (value == prev_value + 1 or value == prev_value - N + 1):
                        row_correctness[i] += 1

                # Check column correctness
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if value == above_value + N:
                        col_correctness[j] += 1

    score += sum(manhattan_distances)

    for i in range(N):
        score -= row_correctness[i] ** 2
        score -= col_correctness[i] ** 2

    return score

