                    prev_value = state[i][j-1]
                    prev_target_i, prev_target_j = divmod(prev_value - 1, N)
                    if (target_j < prev_target_j or target_j > prev_target_j) and target_i == prev_target_i:
                        score += (2 * N / 100.0)
                # Column neighbor penalty
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, above_target_j = divmod(above_value - 1, N)
                    if (target_i < above_target_i or target_i > above_target_i) and target_j == above_target_j:
                        score += (2 * N / 100.0)
    return score

def score_state(state):
    N = len(state)
    score = 0
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                # Row sequence penalty
                expected_row_value = i * N + (j % N) + 1
                if j > 0 and state[i][j-1] != 0:
                    if state[i][j-1] != expected_row_value - 1:
                        score += 2
                # Column sequence penalty
                expected_col_value = (i % N) * N + j + 1
                if i > 0 and state[i-1][j] != 0:
                    if state[i-1][j] != expected_col_value - N:
                        score += 2
    return score

