def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]

    def calculate_manhattan(i, j, value):
        target_i, target_j = divmod(value - 1, N)
        return abs(i - target_i) + abs(j - target_j)

    for i in range(N):
        for j in range(N):
            if not visited[i][j] and state[i][j] != 0:
                cycle_length = 0
                current_i, current_j = i, j
                while not visited[current_i][current_j]:
                    cycle_length += 1
                    score += calculate_manhattan(current_i, current_j, state[current_i][current_j])
                    visited[current_i][current_j] = True
                    next_value = state[current_i][current_j]
                    next_i, next_j = divmod(next_value - 1, N)
                    current_i, current_j = next_i, next_j

                if cycle_length > 1:
                    score += (cycle_length - 3) * 2

    return score

def score_state(state):
