                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                row_sequence[i].append((value, j))
                col_sequence[j].append((value, i))

    for seq in row_sequence + col_sequence:
        sorted_seq = sorted(seq, key=lambda x: x[0])
        misplaced_count = 0
        for (val1, pos1), (val2, pos2) in zip(sorted_seq, sorted_seq[1:]):
            if val1 > val2 or (val1 < val2 and pos1 > pos2):
                misplaced_count += 1
        score += misplaced_count

    return score

