        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                # Penalty for disrupting row order
                if j > 0 and (state[i][j-1], value) not in correct_row_neighbors[i]:
                    score += 1
                # Penalty for disrupting column order
                if i > 0 and (state[i-1][j], value) not in correct_col_neighbors[j]:
                    score += 1

