def score_state(state):
    N = len(state)
    score = 0
    blocked_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Check row conflicts
                for k in range(j + 1, N):
                    other_value = state[i][k]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if i == other_target_i and target_j > other_target_j:
                            blocked_tiles.add((i, k))

                # Check column conflicts
                for k in range(i + 1, N):
                    other_value = state[k][j]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if j == other_target_j and target_i > other_target_i:
                            blocked_tiles.add((k, j))

    # Add penalty for each blocked tile
    score += len(blocked_tiles) * 2

    return score

