                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                # Check for blocking tiles in the row
                for k in range(N):
                    other_value = state[i][k]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if other_target_i == i and other_target_j < target_j and k > j:
                            blocked_tiles.add(value)
                # Check for blocking tiles in the column
                for k in range(N):
                    other_value = state[k][j]
                    if other_value != 0:
                        other_target_i, other_target_j = divmod(other_value - 1, N)
                        if other_target_j == j and other_target_i < target_i and k > i:
                            blocked_tiles.add(value)

    score += len(blocked_tiles) * 2
    return score

def score_state(state):
    N = len(state)
