            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                # Calculate proximity to other misplaced tiles
                for ni in range(max(0, i-1), min(N, i+2)):
                    for nj in range(max(0, j-1), min(N, j+2)):
                        if (ni != i or nj != j) and state[ni][nj] != 0:
                            target_ni, target_nj = divmod(state[ni][nj] - 1, N)
                            if ni != target_ni or nj != target_nj:
                                misplaced_proximity[i][j] += 1

    for i in range(N):
        for j in range(N):
            score += misplaced_proximity[i][j]

    return score

