                for k in range(j + 1, N):
                    if state[k][i] != 0 and col_value > state[k][i]:
                        col_inversions += 1

            last_col_value = col_value

        score += row_sequence_penalty + col_sequence_penalty + 2 * (row_inversions + col_inversions)

