        sorted_row_values = sorted(row_values, key=lambda x: x[0])
        sorted_col_values = sorted(col_values, key=lambda x: x[0])

        for (value, pos), (_, expected_pos) in zip(row_values, sorted_row_values):
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(pos - target_j)
                misplaced_row_deviation[i] += abs(pos - expected_pos)

        for (value, pos), (_, expected_pos) in zip(col_values, sorted_col_values):
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(pos - target_i) + abs(i - target_j)
                misplaced_col_deviation[i] += abs(pos - expected_pos)

    for i in range(N):
        score += misplaced_row_deviation[i] + misplaced_col_deviation[i]

