def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]

    def dfs(i, j, target_i, target_j, group_size):
        if i < 0 or i >= N or j < 0 or j >= N or state[i][j] == 0 or visited[i][j]:
            return 0
        visited[i][j] = True
        correct_neighbors = 0
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_target_i, n_target_j = divmod(state[ni][nj] - 1, N)
                if (n_target_i == target_i and abs(n_target_j - target_j) == 1) or \
                   (n_target_j == target_j and abs(n_target_i - target_i) == 1):
                    correct_neighbors += 1
        group_size[0] += 1
        return correct_neighbors

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0 and not visited[i][j]:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                group_size = [0]
                correct_neighbors = dfs(i, j, target_i, target_j, group_size)
                if group_size[0] == 1 or correct_neighbors == 0:
                    score += 5 * manhattan_distance
                else:
                    score += (group_size[0] - correct_neighbors) * manhattan_distance

    return score

