def score_state(state):
    N = len(state)
    score = 0
    correct_positions_row = [set() for _ in range(N)]
    correct_positions_col = [set() for _ in range(N)]

    # Calculate Manhattan distances and identify correct positions
    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                if i == target_i and j == target_j:
                    correct_positions_row[i].add(value)
                    correct_positions_col[j].add(value)

    # Calculate penalties for isolated tiles and bonuses for chains
    for i in range(N):
        row = state[i]
        chain_length = 0
        previous_value = None
        for j in range(N):
            value = row[j]
            if value != 0:
                if value in correct_positions_row[i]:
                    if previous_value is not None and previous_value + 1 == value or previous_value - N + 1 == value:
                        chain_length += 1
                    else:
                        if chain_length > 1:
                            score -= (chain_length - 1) * 0.5
                        chain_length = 1
                else:
                    if chain_length > 1:
                        score -= (chain_length - 1) * 0.5
                    chain_length = 0
                    # Penalty for isolated tiles
                    if j == 0 or j == N-1 or state[i][j-1] not in correct_positions_row[i] and state[i][j+1] not in correct_positions_row[i]:
                        score += 1
                previous_value = value
        if chain_length > 1:
            score -= (chain_length - 1) * 0.5

    for j in range(N):
        chain_length = 0
        previous_value = None
        for i in range(N):
            value = state[i][j]
            if value != 0:
                if value in correct_positions_col[j]:
                    if previous_value is not None and previous_value + N == value or previous_value + 1 == value:
                        chain_length += 1
                    else:
                        if chain_length > 1:
                            score -= (chain_length - 1) * 0.5
                        chain_length = 1
                else:
                    if chain_length > 1:
                        score -= (chain_length - 1) * 0.5
                    chain_length = 0
                    # Penalty for isolated tiles
                    if i == 0 or i == N-1 or state[i-1][j] not in correct_positions_col[j] and state[i+1][j] not in correct_positions_col[j]:
                        score += 1
                previous_value = value
        if chain_length > 1:
            score -= (chain_length - 1) * 0.5

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        # Calculate row disorder
        row_disorder = 0
        sorted_row = [state[i][j] for j in range(N) if state[i][j] != 0]
        sorted_row.sort()
        for j in range(N - 1):
            if state[i][j] == 0 or state[i][j + 1] == 0:
                continue
            if (state[i][j] > state[i][j + 1]) and (sorted_row.index(state[i][j]) < sorted_row.index(state[i][j + 1])):
                row_disorder += 1

        # Calculate column disorder
        col_disorder = 0
        sorted_col = [state[j][i] for j in range(N) if state[j][i] != 0]
        sorted_col.sort()
        for j in range(N - 1):
            if state[j][i] == 0 or state[j + 1][i] == 0:
                continue
            if (state[j][i] > state[j + 1][i]) and (sorted_col.index(state[j][i]) < sorted_col.index(state[j + 1][i])):
                col_disorder += 1

        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                score += row_disorder * 0.5
                score += col_disorder * 0.25

    return score

