                    next_target_i, next_target_j = divmod(next_value - 1, N)
                    if next_target_i != target_i or next_target_j != target_j + 1:
                        misplaced_neighbors_count[i][j] += 1
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, above_target_j = divmod(above_value - 1, N)
                    if above_target_i != target_i - 1 or above_target_j != target_j:
                        misplaced_neighbors_count[i][j] += 1
                if i < N - 1 and state[i+1][j] != 0:
                    below_value = state[i+1][j]
                    below_target_i, below_target_j = divmod(below_value - 1, N)
                    if below_target_i != target_i + 1 or below_target_j != target_j:
                        misplaced_neighbors_count[i][j] += 1

                # Apply penalty based on number of misplaced neighbors
                penalty_factor = misplaced_neighbors_count[i][j]
                score += penalty_factor * manhattan_distance

    return score

def score_state(state):
