                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == target_i and abs((value - prev_value) % N) not in [1, N - 1]:
                        score += manhattan_distance
                # Check column neighbor penalty
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == target_j and abs((value - above_value) // N) not in [1, N - 1]:
