                penalty_factor_row = (manhattan_distance + i - target_i) ** 0.5
                penalty_factor_col = (manhattan_distance + j - target_j) ** 0.5
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
