                        score += penalty_factor_row
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, above_target_j = divmod(above_value - 1, N)
                    if above_target_j == j and target_i < above_target_i or above_target_i == i and target_j < above_target_j:
                        score += penalty_factor_col
    return score

def score_state(state):
    N = len(state)
    score = 0
    correct_neighbors_count = [[0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Count correct neighbors
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, _ = divmod(above_value - 1, N)
                    if above_target_i == target_i:
                        correct_neighbors_count[i][j] += 1

                if i < N - 1 and state[i+1][j] != 0:
                    below_value = state[i+1][j]
                    below_target_i, _ = divmod(below_value - 1, N)
                    if below_target_i == target_i:
                        correct_neighbors_count[i][j] += 1

                if j > 0 and state[i][j-1] != 0:
                    left_value = state[i][j-1]
                    _, left_target_j = divmod(left_value - 1, N)
                    if left_target_j == target_j:
                        correct_neighbors_count[i][j] += 1

                if j < N - 1 and state[i][j+1] != 0:
                    right_value = state[i][j+1]
                    _, right_target_j = divmod(right_value - 1, N)
                    if right_target_j == target_j:
                        correct_neighbors_count[i][j] += 1

                # Apply penalty based on edge distance and neighbor count
                edge_distance = min(i, j, N-1-i, N-1-j)
                penalty_factor = (N - edge_distance) / N
                score += penalty_factor * max(0, 4 - correct_neighbors_count[i][j])

    return score

