        value = state[i][j]
        if value != 0:
            target_i, target_j = divmod(value - 1, N)
            penalty_factor = abs(target_i - i) + abs(target_j - j) + 1
            isolated = True

            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                    neighbor_value = state[ni][nj]
                    neighbor_target_i, neighbor_target_j = divmod(neighbor_value - 1, N)

                    if (ni == target_i or nj == target_j) and (neighbor_target_i == target_i or neighbor_target_j == target_j):
                        isolated = False
                        break

            if isolated:
                score += penalty_factor ** 0.75

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                calculate_isolation_penalty(i, j)

    return score

