def score_state(state):
    N = len(state)
    score = 0
    visited = [[False] * N for _ in range(N)]
    correct_positions_row = [set() for _ in range(N)]
    correct_positions_col = [set() for _ in range(N)]

    def dfs(i, j, cluster_size):
        if i < 0 or i >= N or j < 0 or j >= N or visited[i][j] or state[i][j] == 0:
            return 0
        target_i, target_j = divmod(state[i][j] - 1, N)
        if target_i != i or target_j != j:
            return 0
        visited[i][j] = True
        cluster_size[0] += 1
        dfs(i + 1, j, cluster_size)
        dfs(i - 1, j, cluster_size)
        dfs(i, j + 1, cluster_size)
        dfs(i, j - 1, cluster_size)
        return cluster_size[0]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance
                correct_positions_row[target_i].add(value)
                correct_positions_col[target_j].add(value)

    for i in range(N):
        for j in range(N):
            if not visited[i][j] and state[i][j] != 0:
                cluster_size = [0]
                size = dfs(i, j, cluster_size)
                if size > 1:
                    score += (size - 1) * 2

    return score

