                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    prev_target_i, prev_target_j = divmod(prev_value - 1, N)
                    if prev_target_i == target_i and abs(prev_target_j - target_j) == 1:
                        in_sequence_count_row[i] += 1
                    else:
                        score += (in_sequence_count_row[i] ** 2) * 0.5
                        in_sequence_count_row[i] = 0

                # Check column sequence
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, above_target_j = divmod(above_value - 1, N)
                    if above_target_j == target_j and abs(above_target_i - target_i) == 1:
                        in_sequence_count_col[j] += 1
                    else:
                        score += (in_sequence_count_col[j] ** 2) * 0.5
                        in_sequence_count_col[j] = 0

    # Final sequence penalty at the end of rows and columns
    for count in in_sequence_count_row + in_sequence_count_col:
        score += (count ** 2) * 0.5

    return score

