        contiguous_sequence = False
        for j in range(N - 1):
            if row[j] != 0 and row[j + 1] != 0:
                target_j, _ = divmod(row[j] - 1, N)
                target_j_next, _ = divmod(row[j + 1] - 1, N)
                if (target_j == j and target_j_next == j + 1) or (row[j] + 1 == row[j + 1]):
                    contiguous_sequence = True
                else:
                    if contiguous_sequence:
                        contiguous_sequence = False
                    else:
                        score += 0.25  # Reduced bonus for non-contiguous correct tiles

    return score

