            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

            # Calculate row penalty
            neighbors = []
            if j > 0 and state[i][j-1] != 0:
                neighbors.append(state[i][j-1])
            if j < N - 1 and state[i][j+1] != 0:
                neighbors.append(state[i][j+1])
            if i > 0 and state[i-1][j] != 0:
                neighbors.append(state[i-1][j])
            if i < N - 1 and state[i+1][j] != 0:
                neighbors.append(state[i+1][j])

            for neighbor in neighbors:
                if value != 0 and (value - 1) // N == (neighbor - 1) // N:
                    expected = value + 1 if j < N - 1 else value - 1
                    if neighbor != expected:
                        row_penalty += 1
                if value != 0 and (value - 1) % N == (neighbor - 1) % N:
                    expected = value + N if i < N - 1 else value - N
                    if neighbor != expected:
                        col_penalty += 1

        score += row_penalty * 1.5
        score += col_penalty * 1.5

    return score

