def score_state(state):
    N = len(state)
    score = 0

    # Calculate Manhattan distances and count misplaced tiles in rows and columns
    misplaced_in_row = [0] * N
    misplaced_in_col = [0] * N

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                manhattan_distance = abs(i - target_i) + abs(j - target_j)
                score += manhattan_distance

                # Count misplaced tiles in rows and columns
                if j > 0 and state[i][j-1] != 0:
                    prev_value = state[i][j-1]
                    if (prev_value - 1) // N == i and value != prev_value + 1:
                        misplaced_in_row[i] += 1

                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    if (above_value - 1) % N == j and value != above_value + N:
                        misplaced_in_col[j] += 1

    # Apply logarithmic penalty for misplaced tiles in rows and columns
    for i in range(N):
        if misplaced_in_row[i] > 0:
            score += (misplaced_in_row[i] * math.log(misplaced_in_row[i] + 1, N))

    for j in range(N):
        if misplaced_in_col[j] > 0:
            score += (misplaced_in_col[j] * math.log(misplaced_in_col[j] + 1, N))

    return score

