                    prev_target_i, prev_target_j = divmod(prev_value - 1, N)
                    if prev_target_i == target_i and prev_target_j > target_j:
                        score += 3

                # Check column neighbor penalty
                if i > 0 and state[i-1][j] != 0:
                    above_value = state[i-1][j]
                    above_target_i, above_target_j = divmod(above_value - 1, N)
                    if above_target_j == target_j and above_target_i > target_i:
                        score += 3

    for dist in max_row_distances + max_col_distances:
        score += dist * 0.75

    return score

